'use client';

import * as React from 'react';

import { Segmented } from '@/components/ui/workspace-kit/primitives';
import { addDays } from '@/components/ui/data-rooms/format';
import type { Room } from '@/components/ui/data-rooms/types';

/** When access granted by an invite or a folder share runs out. */
export type AccessEnd = '7d' | '30d' | 'room-closes' | 'never';

/** The choices that make sense for a room: "when the room closes" only if it has a close date. */
export function accessEndChoices(room: Room): { value: AccessEnd; label: string }[] {
	return [
		{ value: '7d', label: 'In 7 days' },
		{ value: '30d', label: 'In 30 days' },
		...(room.closesAt ? [{ value: 'room-closes' as const, label: 'When room closes' }] : []),
		{ value: 'never', label: 'Never' },
	];
}

/** The end date for a choice, measured from the workspace clock. `undefined` means access doesn't end. */
export function resolveAccessEnd(choice: AccessEnd, room: Room, clock: string): string | undefined {
	switch (choice) {
		case '7d':
			return addDays(clock, 7);
		case '30d':
			return addDays(clock, 30);
		case 'room-closes':
			return room.closesAt;
		case 'never':
			return undefined;
	}
}

export function AccessEndPicker({ room, value, onChange, className }: { room: Room; value: AccessEnd; onChange: (value: AccessEnd) => void; className?: string }) {
	return <Segmented label="Access ends" value={value} options={accessEndChoices(room)} onChange={onChange} className={className} />;
}

'use client';

import { Building2, Droplets, Eye, FileSignature, Lock, type LucideIcon, Network, Users } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Switch } from '@/components/ui/switch';
import {
	CANVAS_NODE_ATTRIBUTE,
	CanvasSurface,
	CanvasWire,
	CanvasZoomControls,
	NodeIconTile,
	NodeShell,
	useCanvasViewport,
	type WirePoint,
	type WireTone,
} from '@/components/ui/workspace-kit/canvas';
import { focusRingClass, ToneBadge, ViewHeader } from '@/components/ui/workspace-kit/primitives';
import { dashedRule, Panel } from '@/components/ui/workspace-kit/surface';
import { type EffectiveAccess, effectiveAccess, leadsUnit, roomPeople, rootUnit } from '@/components/ui/data-rooms/access';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { ChoiceSelect, LEVEL_PRESENTATION } from '@/components/ui/data-rooms/parts';
import type { InheritancePolicy, OrgUnit, Room } from '@/components/ui/data-rooms/types';
import { useCommand } from '@/components/ui/data-rooms/use-command';

const COLUMN_WIDTH = 240;
const COLUMN_GAP = 32;
const UNIT_HEIGHT = 96;
const ROOM_HEIGHT = 148;
const ROW_GAP = 64;

type UnitBox = { unit: OrgUnit; x: number; y: number; depth: number };
type RoomBox = { room: Room; x: number; y: number };
type Wire = { id: string; start: WirePoint; end: WirePoint; to: { kind: 'unit' | 'room'; id: string } };

/**
 * Deterministic top-down tree: each unit sits centred over its children, which
 * are its sub-units first and then the rooms it owns, side by side. Rows share
 * one height so wires run straight down between levels.
 */
function useLayout() {
	const { data } = useDataRooms();
	return React.useMemo(() => {
		const root = rootUnit(data);
		const rooms = data.rooms.filter((room) => room.status !== 'archived');
		const rowHeight = Math.max(UNIT_HEIGHT, ROOM_HEIGHT) + ROW_GAP;
		type TreeNode = { kind: 'unit'; unit: OrgUnit; children: TreeNode[] } | { kind: 'room'; room: Room };
		const build = (unit: OrgUnit, seen: Set<string>): TreeNode => {
			seen.add(unit.id);
			const subUnits = data.units.filter((candidate) => candidate.parentId === unit.id && !seen.has(candidate.id));
			return {
				kind: 'unit',
				unit,
				children: [
					...subUnits.map((child) => build(child, seen)),
					...rooms.filter((room) => room.unitId === unit.id).map((room) => ({ kind: 'room' as const, room })),
				],
			};
		};
		if (!root) return { units: [] as UnitBox[], rooms: [] as RoomBox[], wires: [] as Wire[], width: COLUMN_WIDTH, height: UNIT_HEIGHT };
		const tree = build(root, new Set());
		const widths = new Map<TreeNode, number>();
		const measure = (node: TreeNode): number => {
			const width =
				node.kind === 'room' || node.children.length === 0
					? COLUMN_WIDTH
					: Math.max(COLUMN_WIDTH, node.children.reduce((sum, child) => sum + measure(child), 0) + COLUMN_GAP * (node.children.length - 1));
			widths.set(node, width);
			return width;
		};
		const width = measure(tree);

		const units: UnitBox[] = [];
		const roomBoxes: RoomBox[] = [];
		const wires: Wire[] = [];
		const place = (node: TreeNode, left: number, depth: number, parentAnchor?: WirePoint) => {
			const x = left + ((widths.get(node) ?? COLUMN_WIDTH) - COLUMN_WIDTH) / 2;
			const y = depth * rowHeight;
			const top: WirePoint = [x + COLUMN_WIDTH / 2, y];
			if (node.kind === 'room') {
				roomBoxes.push({ room: node.room, x, y });
				if (parentAnchor) wires.push({ id: `room-${node.room.id}`, start: parentAnchor, end: top, to: { kind: 'room', id: node.room.id } });
				return;
			}
			units.push({ unit: node.unit, x, y, depth });
			if (parentAnchor) wires.push({ id: `unit-${node.unit.id}`, start: parentAnchor, end: top, to: { kind: 'unit', id: node.unit.id } });
			const anchor: WirePoint = [x + COLUMN_WIDTH / 2, y + UNIT_HEIGHT];
			const childrenWidth = node.children.reduce((sum, child) => sum + (widths.get(child) ?? COLUMN_WIDTH), 0) + COLUMN_GAP * Math.max(0, node.children.length - 1);
			let cursor = left + ((widths.get(node) ?? COLUMN_WIDTH) - childrenWidth) / 2;
			for (const child of node.children) {
				place(child, cursor, depth + 1, anchor);
				cursor += (widths.get(child) ?? COLUMN_WIDTH) + COLUMN_GAP;
			}
		};
		place(tree, 0, 0);
		const height = Math.max(UNIT_HEIGHT, ...roomBoxes.map((box) => box.y + ROOM_HEIGHT), ...units.map((box) => box.y + UNIT_HEIGHT));
		return { units, rooms: roomBoxes, wires, width, height };
	}, [data]);
}

/** Inherited membership on a node means its wire carries access down. */
function carried(access: EffectiveAccess | undefined) {
	return Boolean(access?.grants.some((grant) => grant.kind === 'membership' && grant.inherited));
}

function NodeBadge({ access }: { access: EffectiveAccess | undefined }) {
	if (!access) return null;
	if (access.level === 'none') {
		const ruledOut = access.ignored.find((entry) => entry.reason === 'restricted' || entry.reason === 'not-inherited' || entry.reason === 'expired');
		if (!ruledOut) return null;
		const note =
			ruledOut.reason === 'restricted' ? 'Not carried in: restricted room' : ruledOut.reason === 'expired' ? 'Access expired' : 'Not carried in by the organization';
		return <span className="text-[0.6875rem] text-muted-foreground">{note}</span>;
	}
	const presentation = LEVEL_PRESENTATION[access.level];
	const inherited = carried(access);
	return (
		<span className="flex items-center gap-1.5">
			<ToneBadge tone={presentation.tone}>{presentation.label}</ToneBadge>
			{inherited ? <span className="text-[0.6875rem] text-muted-foreground">inherited</span> : null}
		</span>
	);
}

const POLICY_ICONS: { key: keyof Room['policies']; label: string; icon: LucideIcon }[] = [
	{ key: 'restricted', label: 'Restricted', icon: Lock },
	{ key: 'viewOnly', label: 'View only', icon: Eye },
	{ key: 'watermark', label: 'Watermark', icon: Droplets },
	{ key: 'requireAgreement', label: 'Agreement required', icon: FileSignature },
];

function UnitNode({ box, access, dimmed }: { box: UnitBox; access?: EffectiveAccess; dimmed: boolean }) {
	const { data } = useDataRooms();
	const members = data.memberships.filter((membership) => membership.scope.kind === 'unit' && membership.scope.id === box.unit.id && membership.status === 'active');
	const admins = members.filter((membership) => membership.owner || membership.admin).length;
	return (
		<NodeShell
			{...{ [CANVAS_NODE_ATTRIBUTE]: '' }}
			selected={Boolean(access && access.level !== 'none')}
			className={cn('absolute transition-opacity duration-(--duration-moderate) motion-reduce:transition-none', dimmed && 'opacity-40')}
			style={{ left: box.x, top: box.y, width: COLUMN_WIDTH, height: UNIT_HEIGHT }}
			cardClassName="flex-1"
			innerClassName="flex flex-col gap-1.5 p-3"
		>
			<div className="flex items-center gap-2">
				<NodeIconTile icon={box.depth === 0 ? Building2 : Users} />
				<div className="min-w-0 flex-1">
					<p title={box.unit.name} className="truncate text-[0.8125rem] font-medium text-foreground">{box.unit.name}</p>
					<p title={box.unit.kind} className="truncate text-[0.6875rem] text-muted-foreground">{box.unit.kind}</p>
				</div>
			</div>
			<div className="mt-auto flex items-center justify-between gap-2">
				<span className="text-[0.6875rem] text-muted-foreground tabular-nums">
					{members.length} members · {admins} {admins === 1 ? 'admin' : 'admins'}
				</span>
				<NodeBadge access={access} />
			</div>
		</NodeShell>
	);
}

function RoomNode({ box, access, dimmed }: { box: RoomBox; access?: EffectiveAccess; dimmed: boolean }) {
	const { data, openRoom } = useDataRooms();
	const { room } = box;
	const people = roomPeople(data, room.id).filter((row) => row.access.grants.length > 0);
	const guests = people.filter((row) => row.person.guest).length;
	const documents = data.documents.filter((document) => document.roomId === room.id).length;
	const shareOnly = access?.level === 'share';
	return (
		<NodeShell
			{...{ [CANVAS_NODE_ATTRIBUTE]: '' }}
			selected={Boolean(access && access.level !== 'none')}
			className={cn('absolute transition-opacity duration-(--duration-moderate) motion-reduce:transition-none', dimmed && 'opacity-40')}
			style={{ left: box.x, top: box.y, width: COLUMN_WIDTH, height: ROOM_HEIGHT }}
			cardClassName="flex-1"
		>
			<button
				type="button"
				onClick={() => openRoom(room.id)}
				aria-label={`Open ${room.name}`}
				className={cn('flex size-full cursor-pointer flex-col gap-1.5 p-3 text-start hover:bg-overlay-hover', focusRingClass)}
			>
				<span className="flex items-start gap-2">
					<span title={room.name} className="min-w-0 flex-1 truncate text-[0.8125rem] font-medium text-foreground">{room.name}</span>
					<span className="flex shrink-0 gap-1 text-muted-foreground">
						{POLICY_ICONS.filter((policy) => room.policies[policy.key]).map((policy) => (
							<policy.icon key={policy.key} aria-label={policy.label} className="size-3" />
						))}
					</span>
				</span>
				<span className="line-clamp-2 text-[0.6875rem] text-muted-foreground">{room.description}</span>
				<span className="text-[0.6875rem] text-muted-foreground tabular-nums">
					{people.length} people · {guests} {guests === 1 ? 'guest' : 'guests'} · {documents} docs
				</span>
				<span className="mt-auto flex min-h-5 items-center">
					{shareOnly ? <ToneBadge tone="info">Folder access</ToneBadge> : <NodeBadge access={access} />}
				</span>
			</button>
		</NodeShell>
	);
}

const INHERITANCE_ROWS: { key: keyof InheritancePolicy; label: string; description: string }[] = [
	{ key: 'owners', label: 'Owners carry down', description: 'Owners of a unit can open every sub-unit and room below it.' },
	{ key: 'admins', label: 'Admins carry down', description: 'Admins of a unit can open and manage every sub-unit and room below it.' },
	{ key: 'members', label: 'Members carry down', description: 'Members join open rooms below their unit with their role. Restricted rooms still need an invite.' },
	{ key: 'allowGuests', label: 'Allow guests', description: 'People from outside the organization can be invited to rooms and folders.' },
];

function InheritancePanel() {
	const { data, actingId } = useDataRooms();
	const { run, pending, error, locked } = useCommand();
	const root = rootUnit(data);
	const leads = root ? leadsUnit(data, actingId, root.id) : false;
	const disabled = locked || !leads;

	return (
		<Panel
			title="Inheritance"
			description={
				disabled
					? locked
						? 'Exit the preview to change how access carries down.'
						: `Only owners and admins of ${root?.name ?? 'the organization'} can change this.`
					: 'How access carries from a unit into the sub-units and rooms below it.'
			}
			footer={
				<ul className="flex flex-col gap-1.5">
					<li className="flex items-center gap-2">
						<svg aria-hidden="true" width="28" height="8" className="shrink-0">
							<path d="M0 4 H28" stroke="color-mix(in oklab, var(--primary) 55%, transparent)" strokeDasharray="4 4" />
						</svg>
						Access carried down to the selected person
					</li>
					<li className="flex items-center gap-2">
						<svg aria-hidden="true" width="28" height="8" className="shrink-0">
							<path d="M0 4 H28" stroke="color-mix(in oklab, var(--foreground) 20%, transparent)" />
						</svg>
						Belongs to
					</li>
					<li className="flex items-center gap-2">
						<ToneBadge tone="info">Folder access</ToneBadge>
						Only shared folders in the room
					</li>
				</ul>
			}
		>
			<ul className="flex flex-col">
				{INHERITANCE_ROWS.map((row, index) => {
					const id = `inheritance-${row.key}`;
					return (
						<li key={row.key} className={cn('flex items-start gap-3 py-2', index > 0 && cn('border-t', dashedRule))}>
							<div className="min-w-0 flex-1">
								<label htmlFor={id} className="text-[0.8125rem] font-medium text-foreground">
									{row.label}
								</label>
								<p className="text-pretty text-xs text-muted-foreground">{row.description}</p>
							</div>
							<Switch
								id={id}
								className="-my-2.5 -me-1.5"
								checked={data.inheritance[row.key]}
								disabled={disabled || pending}
								onCheckedChange={(checked) => void run({ type: 'update-inheritance', inheritance: { ...data.inheritance, [row.key]: checked } })}
							/>
						</li>
					);
				})}
			</ul>
			{error ? (
				<p role="alert" className="mt-2 text-[0.8125rem] text-destructive">
					{error}
				</p>
			) : null}
		</Panel>
	);
}

/**
 * The organization as a tree: units, their sub-units, and the rooms each
 * owns. Pick a person to see where their access reaches, what carries down
 * from above, and where it stops.
 */
export function AccessMapView() {
	const { data, person } = useDataRooms();
	const layout = useLayout();
	const viewport = useCanvasViewport(layout.width, { fit: 'contain', contentHeight: layout.height, minFitZoom: 0.6 });
	const [selected, setSelected] = React.useState<string>('');
	const selectId = React.useId();

	const accessFor = React.useMemo(() => {
		if (!selected) return null;
		const units = new Map(layout.units.map((box) => [box.unit.id, effectiveAccess(data, selected, { kind: 'unit', unitId: box.unit.id })]));
		const rooms = new Map(layout.rooms.map((box) => [box.room.id, effectiveAccess(data, selected, { kind: 'room', roomId: box.room.id })]));
		return { units, rooms };
	}, [data, layout, selected]);

	const wireTone = (wire: Wire): WireTone => {
		if (!accessFor) return 'rest';
		const access = wire.to.kind === 'unit' ? accessFor.units.get(wire.to.id) : accessFor.rooms.get(wire.to.id);
		return carried(access) ? 'live' : 'rest';
	};

	const members = data.people.filter((entry) => !entry.guest);
	const guests = data.people.filter((entry) => entry.guest);
	const chosen = selected ? person(selected) : undefined;
	const reach = accessFor ? [...accessFor.rooms.values()].filter((access) => access.level !== 'none').length : 0;

	return (
		<section aria-label="Access map" className="flex min-w-0 flex-1 flex-col">
			<ViewHeader icon={Network} title="Access map" />
			<div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-3 @4xl/view:overflow-hidden">
				{/* The prompt and the picker it asks for read as one line, above both the map and the panel, so those two
				    share a top edge. The prompt never changes, so the picker stays put; the result follows it. */}
				<div className="flex flex-wrap items-center gap-x-2 gap-y-1.5 px-1">
					<p className="text-[0.8125rem] text-muted-foreground">Pick a person to see where their access reaches.</p>
					<label htmlFor={selectId} className="sr-only">
						Show access for
					</label>
					<ChoiceSelect
						id={selectId}
						value={selected}
						onValueChange={setSelected}
						className="w-auto max-w-[14rem] min-w-40"
						options={[
							{ value: '', label: 'Everyone' },
							...members.map((entry) => ({ value: entry.id, label: entry.name, group: data.org.name })),
							...guests.map((entry) => ({ value: entry.id, label: entry.company ? `${entry.name} · ${entry.company}` : entry.name, group: 'Guests' })),
						]}
					/>
					<p aria-live="polite" className="text-[0.8125rem] font-medium text-foreground tabular-nums">
						{chosen ? `Can enter ${reach} of ${layout.rooms.length} rooms.` : null}
					</p>
				</div>
				<div className="flex min-h-0 flex-1 flex-col gap-3 @4xl/view:flex-row">
					<div className="min-h-[26rem] min-w-0 flex-1">
						<CanvasSurface
							viewport={viewport}
							label="Access map. Drag or use arrow keys to pan; plus and minus to zoom."
							onPaneClick={() => setSelected('')}
							overlay={<CanvasZoomControls viewport={viewport} fit />}
						>
							<svg aria-hidden="true" className="pointer-events-none absolute top-0 start-0 overflow-visible" width={layout.width} height={layout.height}>
								{layout.wires.map((wire) => (
									<CanvasWire key={wire.id} start={wire.start} end={wire.end} axis="vertical" tone={wireTone(wire)} />
								))}
							</svg>
							{layout.units.map((box) => {
								const access = accessFor?.units.get(box.unit.id);
								return <UnitNode key={box.unit.id} box={box} access={access} dimmed={Boolean(accessFor) && access?.level === 'none'} />;
							})}
							{layout.rooms.map((box) => {
								const access = accessFor?.rooms.get(box.room.id);
								const visible = access && (access.level !== 'none' || access.grants.length > 0);
								return <RoomNode key={box.room.id} box={box} access={access} dimmed={Boolean(accessFor) && !visible} />;
							})}
						</CanvasSurface>
					</div>
					<div className="shrink-0 @4xl/view:w-[300px] @4xl/view:overflow-y-auto">
						<InheritancePanel />
					</div>
				</div>
			</div>
		</section>
	);
}

'use client';

import { Ban, Building2, Eye, FolderLock, FolderOpen, FolderSymlink, Info } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetDescription, SheetTitle } from '@/components/ui/sheet';
import { ToneBadge } from '@/components/ui/workspace-kit/primitives';
import { StatusBadge } from '@/components/ui/workspace-kit/surface';
import { type AccessGrant, type AccessLimit, describeGrant, describeIgnored, folderName, PERMISSION_COPY } from '@/components/ui/data-rooms/access';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { daysUntil, firstName } from '@/components/ui/data-rooms/format';
import { ChoiceSelect, LEVEL_PRESENTATION, PermissionChips, PersonLine } from '@/components/ui/data-rooms/parts';
import type { Room } from '@/components/ui/data-rooms/types';
import { useCommand } from '@/components/ui/data-rooms/use-command';

type AccessTraceSheetProps = {
	request: { personId: string; roomId: string } | null;
	onOpenChange: (open: boolean) => void;
};

function limitText(limit: AccessLimit) {
	if (limit.reason === 'view-only') return 'View-only documents can’t be downloaded.';
	const names = limit.removed.map((permission) => PERMISSION_COPY[permission].label.toLowerCase());
	return `Read-only: can’t ${names.slice(0, -1).join(', ')}${names.length > 1 ? ', or ' : ''}${names[names.length - 1]}.`;
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
	return (
		<section className="flex flex-col gap-2">
			<h3 className="text-xs text-muted-foreground">{title}</h3>
			{children}
		</section>
	);
}

/** A tile on the chain: a unit or the room. */
function StepTile({ kind, room }: { kind: 'unit' | 'room'; room?: Room }) {
	const Icon = kind === 'unit' ? Building2 : room?.policies.restricted ? FolderLock : FolderOpen;
	return (
		<span aria-hidden="true" className="relative z-10 grid size-6 shrink-0 place-items-center rounded-[7px] bg-card text-muted-foreground shadow-card">
			<Icon className="size-3.5" />
		</span>
	);
}

/** One grant drawn as a path from where it is held down to this room. */
function GrantChain({ grant, room }: { grant: AccessGrant; room: Room }) {
	const { data, unit, role, format } = useDataRooms();
	const text = describeGrant(data, grant, (iso) => format.date(iso));

	if (grant.kind === 'share') {
		const days = grant.expiresAt ? daysUntil(grant.expiresAt, data.clock) : null;
		return (
			<li className="flex items-start gap-3 rounded-lg border border-border bg-card p-3 shadow-2xs">
				<span aria-hidden="true" className="grid size-6 shrink-0 place-items-center rounded-[7px] bg-info/10 text-info">
					<FolderSymlink className="size-3.5" />
				</span>
				<span className="min-w-0 flex-1">
					<span className="block text-[0.8125rem] font-medium text-foreground">{folderName(grant.folder)}</span>
					<span className="block text-xs text-muted-foreground">{text}</span>
					{grant.expiresAt ? (
						<span className={cn('mt-1 block text-xs tabular-nums', days !== null && days <= 7 ? 'text-warning' : 'text-muted-foreground')}>
							Ends {format.deadline(grant.expiresAt)}
						</span>
					) : null}
				</span>
				{grant.partial ? <ToneBadge tone="info">Inside only</ToneBadge> : null}
			</li>
		);
	}

	const badge =
		grant.level === 'member'
			? { label: role(grant.roleId)?.name ?? 'Member', tone: 'neutral' as const }
			: LEVEL_PRESENTATION[grant.level];
	const steps: { key: string; kind: 'unit' | 'room'; name: string; held: boolean }[] = [
		...grant.path.map((unitId, index) => ({ key: unitId, kind: 'unit' as const, name: unit(unitId)?.name ?? 'Unit', held: index === 0 })),
		{ key: room.id, kind: 'room' as const, name: room.name, held: !grant.inherited },
	];

	return (
		<li className="rounded-lg border border-border bg-card p-3 shadow-2xs">
			<ol className="relative flex flex-col gap-3">
				{steps.length > 1 ? <span aria-hidden="true" className="absolute top-3 bottom-3 start-3 w-px bg-border" /> : null}
				{steps.map((step, index) => (
					<li key={step.key} className="relative flex items-center gap-2.5">
						<StepTile kind={step.kind} room={room} />
						<span title={step.name} className={cn('min-w-0 flex-1 truncate text-[0.8125rem]', step.held ? 'font-medium text-foreground' : 'text-muted-foreground')}>{step.name}</span>
						{step.held ? (
							<StatusBadge presentation={badge} />
						) : index > 0 ? (
							<span className="text-xs text-subtle-foreground">carried down</span>
						) : null}
					</li>
				))}
			</ol>
			<p className="mt-2.5 border-t border-dashed border-foreground/10 pt-2 text-xs text-muted-foreground">{text}</p>
		</li>
	);
}

/**
 * Why someone can (or can't) do something in a room: what they can do, every
 * grant drawn as a path from where it's held, the limits applied, access that
 * doesn't count, and a check for any single document.
 */
export function AccessTraceSheet({ request, onOpenChange }: AccessTraceSheetProps) {
	const { data, person, room: findRoom, access, can, setPreviewAs, openRoom, openShare, format } = useDataRooms();
	const { locked } = useCommand();
	const [last, setLast] = React.useState(request);
	if (request && request !== last) setLast(request);
	const current = request ?? last;
	const subject = current ? person(current.personId) : undefined;
	const room = current ? findRoom(current.roomId) : undefined;
	const [documentId, setDocumentId] = React.useState('');
	// Start the document check over for each person and room, during render rather than in an effect.
	const subjectKey = current ? `${current.personId}|${current.roomId}` : '';
	const [checkedFor, setCheckedFor] = React.useState(subjectKey);
	if (checkedFor !== subjectKey) {
		setCheckedFor(subjectKey);
		setDocumentId('');
	}

	if (!current || !subject || !room) {
		return (
			<Sheet open={false} onOpenChange={onOpenChange}>
				<SheetContent side="right" className="hidden" />
			</Sheet>
		);
	}

	const first = firstName(subject.name);
	const result = access({ kind: 'room', roomId: room.id }, subject.id);
	const documents = data.documents.filter((document) => document.roomId === room.id);
	const checked = documentId ? access({ kind: 'document', documentId }, subject.id) : null;
	const manages = can('manage_members', { kind: 'room', roomId: room.id });
	const canShare = can('share', { kind: 'room', roomId: room.id });
	const shareOnly = result.level === 'share';

	return (
		<Sheet open={Boolean(request)} onOpenChange={onOpenChange}>
			<SheetContent side="right" className="w-[27rem] max-w-[92vw] gap-0 p-0 sm:max-w-[27rem]">
				<div className="flex flex-col gap-3 border-b border-border bg-muted/50 px-5 pt-5 pb-4">
					<div className="flex flex-col gap-1">
						<SheetTitle className="text-base font-medium">Why can {first} open this?</SheetTitle>
						<SheetDescription className="text-[0.8125rem]">Access to {room.name}, and where it comes from.</SheetDescription>
					</div>
					<div className="flex items-center justify-between gap-3">
						<PersonLine person={subject} />
						<StatusBadge presentation={LEVEL_PRESENTATION[result.level]} />
					</div>
				</div>
				<div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto px-5 py-5 [&>*]:shrink-0">
					<Section title={shareOnly ? 'Can do in shared folders' : 'Can do here'}>
						<PermissionChips
							permissions={shareOnly ? [...new Set(result.grants.flatMap((grant) => grant.permissions))] : result.permissions}
						/>
					</Section>

					<Section title="Because">
						{result.grants.length ? (
							<ol className="flex flex-col gap-2">
								{result.grants.map((grant) => (
									<GrantChain key={grant.kind === 'share' ? grant.shareId : grant.membershipId} grant={grant} room={room} />
								))}
							</ol>
						) : (
							<p className="flex items-start gap-2 rounded-lg bg-muted/60 px-3 py-2.5 text-[0.8125rem] text-muted-foreground">
								<Info aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
								{first} has no access to this room right now.
							</p>
						)}
					</Section>

					{result.limits.length ? (
						<Section title="Limits">
							<ul className="flex flex-col gap-1.5 text-[0.8125rem] text-foreground">
								{result.limits.map((limit) => (
									<li key={limit.reason}>{limitText(limit)}</li>
								))}
							</ul>
						</Section>
					) : null}

					{result.ignored.length ? (
						<Section title="Not counted">
							<ul className="flex flex-col gap-1.5">
								{result.ignored.map((entry, index) => (
									<li key={entry.membershipId ?? entry.shareId ?? index} className="flex items-start gap-2 text-[0.8125rem] text-muted-foreground">
										<Ban aria-hidden="true" className="mt-0.5 size-3.5 shrink-0 text-subtle-foreground" />
										{describeIgnored(data, entry, (iso) => format.date(iso))}
									</li>
								))}
							</ul>
						</Section>
					) : null}

					<Section title="Check a document">
						<ChoiceSelect
							label="Document to check"
							className="w-full"
							value={documentId}
							onValueChange={setDocumentId}
							options={[
								{ value: '', label: 'Choose a document…' },
								...documents.map((document) => ({
									value: document.id,
									label: `${document.folder === '/' ? '' : `${document.folder.slice(1)} / `}${document.name}`,
								})),
							]}
						/>
						{checked ? (
							<div className="flex flex-col gap-2 rounded-lg bg-muted/60 p-3">
								<p className="text-[0.8125rem] text-foreground">
									{checked.permissions.includes('view') ? `${first} can open it.` : `${first} can’t open it.`}
								</p>
								<PermissionChips permissions={checked.permissions} compact />
								{checked.limits.map((limit) => (
									<p key={limit.reason} className="text-xs text-muted-foreground">
										{limitText(limit)}
									</p>
								))}
							</div>
						) : null}
					</Section>
				</div>
				{manages || canShare ? (
					<div className="flex shrink-0 flex-wrap justify-end gap-2 border-t border-border bg-muted/50 px-5 py-3">
						{canShare ? (
							<Button
								size="xs"
								variant="outline"
								disabled={locked}
								onClick={() => {
									onOpenChange(false);
									openShare({ roomId: room.id, personId: subject.id });
								}}
							>
								<FolderSymlink aria-hidden="true" />
								Share a folder
							</Button>
						) : null}
						{manages && subject.id !== data.viewerId && result.level !== 'none' ? (
							<Button
								size="xs"
								onClick={() => {
									setPreviewAs(subject.id);
									openRoom(room.id);
									onOpenChange(false);
								}}
							>
								<Eye aria-hidden="true" />
								Preview as {first}
							</Button>
						) : null}
					</div>
				) : null}
			</SheetContent>
		</Sheet>
	);
}

import type {
	ActivityEvent,
	DataRoomDocument,
	DataRoomsData,
	FolderShare,
	Membership,
	MembershipScope,
	OrgUnit,
	Permission,
	Person,
	QuestionThread,
	Room,
} from '@/components/ui/data-rooms/types';

/**
 * Effective access for the Data Rooms template. Pure and synchronous, so the
 * UI can gate controls, explain why someone has access, and preview the
 * workspace as another person. It is a reading aid, not a security boundary:
 * the host's own authorization decides every request.
 */

export const ALL_PERMISSIONS: readonly Permission[] = [
	'view',
	'download',
	'upload',
	'edit',
	'delete',
	'share',
	'invite',
	'manage_members',
	'manage_room',
	'ask_assistant',
];

export const PERMISSION_COPY: Record<Permission, { label: string; description: string }> = {
	view: { label: 'View', description: 'Open documents in the viewer.' },
	download: { label: 'Download', description: 'Save a copy, unless the document is view-only.' },
	upload: { label: 'Upload', description: 'Add documents and new versions.' },
	edit: { label: 'Edit', description: 'Rename, move, and change document settings.' },
	delete: { label: 'Delete', description: 'Remove documents.' },
	share: { label: 'Share folders', description: 'Give people access to a folder.' },
	invite: { label: 'Invite', description: 'Invite people to the room.' },
	manage_members: { label: 'Manage people', description: 'Change roles and remove people.' },
	manage_room: { label: 'Manage room', description: 'Change settings, the agreement, and answer questions.' },
	ask_assistant: { label: 'Ask assistant', description: 'Ask questions about documents they can open.' },
};

/** Permissions that change something. Read-only access keeps everything else. */
export const WRITE_PERMISSIONS: readonly Permission[] = ['upload', 'edit', 'delete', 'share', 'invite', 'manage_members', 'manage_room'];

export type AccessTarget =
	| { kind: 'unit'; unitId: string }
	| { kind: 'room'; roomId: string }
	| { kind: 'folder'; roomId: string; folder: string }
	| { kind: 'document'; documentId: string };

export type AccessLevel = 'owner' | 'admin' | 'member' | 'share' | 'none';

export type AccessGrant =
	| {
			kind: 'membership';
			membershipId: string;
			scope: MembershipScope;
			level: 'owner' | 'admin' | 'member';
			/** Held on a parent unit and carried down. */
			inherited: boolean;
			/** Units from where the membership is held down to the target's unit, top first. */
			path: string[];
			roleId?: string;
			permissions: Permission[];
			readOnly: boolean;
	  }
	| {
			kind: 'share';
			shareId: string;
			folder: string;
			expiresAt?: string;
			permissions: Permission[];
			/** True when the target is wider than the shared folder, so the share covers only part of it. */
			partial: boolean;
	  };

/** Access someone would have had, and why it doesn't count. */
export type AccessIgnored = {
	reason: 'pending' | 'suspended' | 'expired' | 'not-inherited' | 'restricted';
	membershipId?: string;
	shareId?: string;
	scope?: MembershipScope;
	level?: 'owner' | 'admin' | 'member';
	at?: string;
};

export type AccessLimit = { reason: 'read-only' | 'view-only'; removed: Permission[] };

export type EffectiveAccess = {
	level: AccessLevel;
	permissions: Permission[];
	grants: AccessGrant[];
	limits: AccessLimit[];
	ignored: AccessIgnored[];
};

const NONE: EffectiveAccess = { level: 'none', permissions: [], grants: [], limits: [], ignored: [] };

const LEVEL_RANK: Record<AccessLevel, number> = { owner: 4, admin: 3, member: 2, share: 1, none: 0 };

/* ------------------------------------------------------------------ *
 * Indexes and caches
 *
 * Data is treated as immutable: every change produces new arrays and a new
 * data object. Lookups are indexed per array and results cached per data
 * object, so the many access checks one render makes cost one pass each.
 * Cached results are shared; treat them as read-only.
 * ------------------------------------------------------------------ */

function indexed<T, K>(cache: WeakMap<readonly T[], Map<K, T>>, rows: readonly T[], key: (row: T) => K) {
	let map = cache.get(rows);
	if (!map) {
		map = new Map(rows.map((row) => [key(row), row]));
		cache.set(rows, map);
	}
	return map;
}

function grouped<T>(cache: WeakMap<readonly T[], Map<string, T[]>>, rows: readonly T[], key: (row: T) => string) {
	let map = cache.get(rows);
	if (!map) {
		map = new Map();
		for (const row of rows) {
			const bucket = map.get(key(row));
			if (bucket) bucket.push(row);
			else map.set(key(row), [row]);
		}
		cache.set(rows, map);
	}
	return map;
}

const UNITS_BY_ID = new WeakMap<readonly OrgUnit[], Map<string, OrgUnit>>();
const ROOMS_BY_ID = new WeakMap<readonly Room[], Map<string, Room>>();
const DOCUMENTS_BY_ID = new WeakMap<readonly DataRoomDocument[], Map<string, DataRoomDocument>>();
const MEMBERSHIPS_BY_PERSON = new WeakMap<readonly Membership[], Map<string, Membership[]>>();
const SHARES_BY_PERSON = new WeakMap<readonly FolderShare[], Map<string, FolderShare[]>>();
const PEOPLE_BY_ID = new WeakMap<readonly Person[], Map<string, Person>>();

/** Memoizes `compute` per data object and key. */
function memoized<T>(cache: WeakMap<DataRoomsData, Map<string, T>>, data: DataRoomsData, key: string, compute: () => T): T {
	let entries = cache.get(data);
	if (!entries) {
		entries = new Map();
		cache.set(data, entries);
	}
	const hit = entries.get(key);
	if (hit !== undefined) return hit;
	const value = compute();
	entries.set(key, value);
	return value;
}

const ACCESS_CACHE = new WeakMap<DataRoomsData, Map<string, EffectiveAccess>>();
const VISIBLE_CACHE = new WeakMap<DataRoomsData, Map<string, DataRoomDocument[]>>();
const PEOPLE_CACHE = new WeakMap<DataRoomsData, Map<string, { person: Person; access: EffectiveAccess }[]>>();

function targetKey(target: AccessTarget) {
	switch (target.kind) {
		case 'unit':
			return `unit:${target.unitId}`;
		case 'room':
			return `room:${target.roomId}`;
		case 'folder':
			return `folder:${target.roomId}:${normalizeFolder(target.folder)}`;
		case 'document':
			return `document:${target.documentId}`;
	}
}

/* ------------------------------------------------------------------ *
 * Paths and structure
 * ------------------------------------------------------------------ */

/** `"02 Financials/"` → `"/02 Financials"`; `""` → `"/"`. */
export function normalizeFolder(path: string) {
	const parts = path.split('/').filter(Boolean);
	return parts.length ? `/${parts.join('/')}` : '/';
}

/** True when `folder` is `container` or sits anywhere below it. */
export function folderContains(container: string, folder: string) {
	const outer = normalizeFolder(container);
	const inner = normalizeFolder(folder);
	return outer === '/' || inner === outer || inner.startsWith(`${outer}/`);
}

/** The folder's name: its last path segment, or the room name at the root. */
export function folderName(path: string, rootName = 'All documents') {
	const normalized = normalizeFolder(path);
	return normalized === '/' ? rootName : normalized.slice(normalized.lastIndexOf('/') + 1);
}

/** The folder above, or null at the root. */
export function parentFolder(path: string) {
	const normalized = normalizeFolder(path);
	if (normalized === '/') return null;
	const index = normalized.lastIndexOf('/');
	return index === 0 ? '/' : normalized.slice(0, index);
}

/** Every folder in a room, from document paths and explicit empty folders, including their parents. Sorted. */
export function roomFolders(data: Pick<DataRoomsData, 'documents' | 'folders'>, roomId: string) {
	const paths = new Set<string>(['/']);
	const add = (path: string) => {
		let current: string | null = normalizeFolder(path);
		while (current && !paths.has(current)) {
			paths.add(current);
			current = parentFolder(current);
		}
	};
	for (const document of data.documents) if (document.roomId === roomId) add(document.folder);
	for (const folder of data.folders ?? []) if (folder.roomId === roomId) add(folder.path);
	return [...paths].sort((a, b) => a.localeCompare(b));
}

/** The unit and its ancestors, nearest first, ending at the organization. Guards against cycles. */
export function unitChain(data: Pick<DataRoomsData, 'units'>, unitId: string): OrgUnit[] {
	const byId = indexed(UNITS_BY_ID, data.units, (unit) => unit.id);
	const chain: OrgUnit[] = [];
	let current = byId.get(unitId);
	while (current && !chain.includes(current)) {
		chain.push(current);
		current = current.parentId ? byId.get(current.parentId) : undefined;
	}
	return chain;
}

/** The organization unit: the one without a parent. */
export function rootUnit(data: Pick<DataRoomsData, 'units'>) {
	return data.units.find((unit) => unit.parentId === null);
}

/** Units directly below a unit. */
export function childUnits(data: Pick<DataRoomsData, 'units'>, unitId: string) {
	return data.units.filter((unit) => unit.parentId === unitId);
}

/* ------------------------------------------------------------------ *
 * Effective access
 * ------------------------------------------------------------------ */

function isPast(iso: string | undefined, clock: string) {
	return iso !== undefined && Date.parse(iso) <= Date.parse(clock);
}

function membershipLevel(membership: Membership): 'owner' | 'admin' | 'member' {
	return membership.owner ? 'owner' : membership.admin ? 'admin' : 'member';
}

function membershipPermissions(data: DataRoomsData, membership: Membership): Permission[] {
	if (membership.owner || membership.admin) return [...ALL_PERMISSIONS];
	const role = data.roles.find((candidate) => candidate.id === membership.roleId) ?? data.roles.find((candidate) => candidate.isDefault);
	return [...new Set([...(role?.permissions ?? []), ...(membership.extraPermissions ?? [])])];
}

function sharePermissions(share: FolderShare): Permission[] {
	const permissions: Permission[] = [];
	if (share.can.view) permissions.push('view', 'download');
	if (share.can.edit) permissions.push('upload', 'edit');
	if (share.can.delete) permissions.push('delete');
	return permissions;
}

function ordered(permissions: Iterable<Permission>) {
	const set = new Set(permissions);
	return ALL_PERMISSIONS.filter((permission) => set.has(permission));
}

type Resolved = { unitId: string; room?: Room; folder?: string; document?: DataRoomDocument };

function resolveTarget(data: DataRoomsData, target: AccessTarget): Resolved | null {
	switch (target.kind) {
		case 'unit':
			return indexed(UNITS_BY_ID, data.units, (unit) => unit.id).has(target.unitId) ? { unitId: target.unitId } : null;
		case 'room': {
			const room = indexed(ROOMS_BY_ID, data.rooms, (candidate) => candidate.id).get(target.roomId);
			return room ? { unitId: room.unitId, room } : null;
		}
		case 'folder': {
			const room = indexed(ROOMS_BY_ID, data.rooms, (candidate) => candidate.id).get(target.roomId);
			return room ? { unitId: room.unitId, room, folder: normalizeFolder(target.folder) } : null;
		}
		case 'document': {
			const document = indexed(DOCUMENTS_BY_ID, data.documents, (candidate) => candidate.id).get(target.documentId);
			const room = document && indexed(ROOMS_BY_ID, data.rooms, (candidate) => candidate.id).get(document.roomId);
			return document && room ? { unitId: room.unitId, room, folder: normalizeFolder(document.folder), document } : null;
		}
	}
}

/**
 * What a person can do on a unit, room, folder, or document, with every grant
 * that contributes, the limits applied, and the access that was ruled out.
 *
 * - Owners and admins hold every permission where they are members, and carry
 *   it into sub-units and rooms when inheritance allows.
 * - Members hold their role plus extra grants, and carry it down only when
 *   inheritance includes members and the room is not restricted.
 * - Folder shares grant view, edit, and delete inside their subtree.
 * - Read-only memberships lose every write permission; view-only documents
 *   lose `download` for anyone who doesn't manage the room.
 * - Pending, suspended, and expired access grants nothing.
 */
export function effectiveAccess(data: DataRoomsData, personId: string, target: AccessTarget): EffectiveAccess {
	return memoized(ACCESS_CACHE, data, `${personId}|${targetKey(target)}`, () => computeAccess(data, personId, target));
}

function computeAccess(data: DataRoomsData, personId: string, target: AccessTarget): EffectiveAccess {
	const resolved = resolveTarget(data, target);
	if (!resolved) return NONE;
	const chain = unitChain(data, resolved.unitId);
	const chainIds = chain.map((unit) => unit.id);
	const grants: AccessGrant[] = [];
	const limits: AccessLimit[] = [];
	const ignored: AccessIgnored[] = [];
	const granted = new Set<Permission>();

	for (const membership of grouped(MEMBERSHIPS_BY_PERSON, data.memberships, (row) => row.personId).get(personId) ?? []) {
		const { scope } = membership;
		let path: string[];
		let inherited: boolean;
		if (scope.kind === 'room') {
			if (!resolved.room || scope.id !== resolved.room.id) continue;
			path = [];
			inherited = false;
		} else {
			const index = chainIds.indexOf(scope.id);
			if (index === -1) continue;
			path = chainIds.slice(0, index + 1).reverse();
			// A unit membership reaches its own unit directly; anything below it is inherited.
			inherited = Boolean(resolved.room) || index > 0;
		}
		const level = membershipLevel(membership);
		if (membership.status !== 'active') {
			ignored.push({ reason: membership.status === 'invited' ? 'pending' : 'suspended', membershipId: membership.id, scope, level });
			continue;
		}
		if (isPast(membership.expiresAt, data.clock)) {
			ignored.push({ reason: 'expired', membershipId: membership.id, scope, level, at: membership.expiresAt });
			continue;
		}
		if (inherited) {
			const allowed = level === 'owner' ? data.inheritance.owners : level === 'admin' ? data.inheritance.admins : data.inheritance.members;
			if (!allowed) {
				ignored.push({ reason: 'not-inherited', membershipId: membership.id, scope, level });
				continue;
			}
			if (level === 'member' && resolved.room?.policies.restricted) {
				ignored.push({ reason: 'restricted', membershipId: membership.id, scope, level });
				continue;
			}
		}
		let permissions = membershipPermissions(data, membership);
		if (membership.readOnly) {
			const removed = permissions.filter((permission) => WRITE_PERMISSIONS.includes(permission));
			if (removed.length) limits.push({ reason: 'read-only', removed });
			permissions = permissions.filter((permission) => !WRITE_PERMISSIONS.includes(permission));
		}
		for (const permission of permissions) granted.add(permission);
		grants.push({
			kind: 'membership',
			membershipId: membership.id,
			scope,
			level,
			inherited,
			path,
			roleId: level === 'member' ? (membership.roleId ?? data.roles.find((role) => role.isDefault)?.id) : undefined,
			permissions: ordered(permissions),
			readOnly: Boolean(membership.readOnly),
		});
	}

	if (resolved.room) {
		for (const share of grouped(SHARES_BY_PERSON, data.shares, (row) => row.personId).get(personId) ?? []) {
			if (share.roomId !== resolved.room.id) continue;
			const folder = resolved.folder ?? '/';
			const covers = folderContains(share.folder, folder);
			const inside = folderContains(folder, share.folder);
			if (!covers && !inside) continue;
			if (isPast(share.expiresAt, data.clock)) {
				ignored.push({ reason: 'expired', shareId: share.id, at: share.expiresAt });
				continue;
			}
			const permissions = sharePermissions(share);
			grants.push({ kind: 'share', shareId: share.id, folder: normalizeFolder(share.folder), expiresAt: share.expiresAt, permissions, partial: !covers });
			// A share on a subfolder doesn't open the wider target, it only shows the way in.
			if (covers) for (const permission of permissions) granted.add(permission);
		}
	}

	const viewOnly = resolved.document
		? Boolean(resolved.room?.policies.viewOnly || resolved.document.restrictions?.viewOnly)
		: false;
	if (viewOnly && granted.has('download') && !granted.has('manage_room')) {
		granted.delete('download');
		limits.push({ reason: 'view-only', removed: ['download'] });
	}

	let level: AccessLevel = 'none';
	for (const grant of grants) {
		const next: AccessLevel = grant.kind === 'share' ? 'share' : grant.level;
		if (LEVEL_RANK[next] > LEVEL_RANK[level]) level = next;
	}
	return { level, permissions: ordered(granted), grants, limits, ignored };
}

export function can(data: DataRoomsData, personId: string, permission: Permission, target: AccessTarget) {
	return effectiveAccess(data, personId, target).permissions.includes(permission);
}

/** A person can enter a room with room-wide view access, or with any live folder share inside it. */
export function canEnterRoom(data: DataRoomsData, personId: string, roomId: string) {
	const access = effectiveAccess(data, personId, { kind: 'room', roomId });
	return access.permissions.includes('view') || access.grants.some((grant) => grant.kind === 'share' && grant.permissions.includes('view'));
}

export function visibleRooms(data: DataRoomsData, personId: string) {
	return data.rooms.filter((room) => canEnterRoom(data, personId, room.id));
}

/**
 * Documents a person can open in a room. Room-wide view opens every document;
 * otherwise only live folder shares do, so this checks the room once rather
 * than every document.
 */
export function visibleDocuments(data: DataRoomsData, personId: string, roomId: string) {
	return memoized(VISIBLE_CACHE, data, `${personId}|${roomId}`, () => {
		const inRoom = data.documents.filter((document) => document.roomId === roomId);
		if (effectiveAccess(data, personId, { kind: 'room', roomId }).permissions.includes('view')) return inRoom;
		const folders = (grouped(SHARES_BY_PERSON, data.shares, (row) => row.personId).get(personId) ?? [])
			.filter((share) => share.roomId === roomId && share.can.view && !isPast(share.expiresAt, data.clock))
			.map((share) => share.folder);
		return folders.length ? inRoom.filter((document) => folders.some((folder) => folderContains(folder, document.folder))) : [];
	});
}

/** Owner or admin of a unit, held there or carried down from a parent unit. */
export function leadsUnit(data: DataRoomsData, personId: string, unitId: string) {
	const { level } = effectiveAccess(data, personId, { kind: 'unit', unitId });
	return level === 'owner' || level === 'admin';
}

/** Leads any unit or manages any room: who gets the access map, activity, and room creation. */
export function managesAnything(data: DataRoomsData, personId: string) {
	return (
		data.units.some((unit) => leadsUnit(data, personId, unit.id)) ||
		data.rooms.some((room) => can(data, personId, 'manage_room', { kind: 'room', roomId: room.id }))
	);
}

const QUESTIONS_CACHE = new WeakMap<DataRoomsData, Map<string, QuestionThread[]>>();
const ACTIVITY_CACHE = new WeakMap<DataRoomsData, Map<string, ActivityEvent[]>>();

/**
 * Q&A threads a person may read in a room. Room managers read every thread;
 * everyone else reads their own and their company's, never another bidder's.
 */
export function visibleQuestions(data: DataRoomsData, personId: string, roomId: string) {
	return memoized(QUESTIONS_CACHE, data, `${personId}|${roomId}`, () => {
		const inRoom = data.questions.filter((question) => question.roomId === roomId);
		if (can(data, personId, 'manage_room', { kind: 'room', roomId })) return inRoom;
		const people = indexed(PEOPLE_BY_ID, data.people, (row) => row.id);
		const company = people.get(personId)?.company;
		return inRoom.filter((question) => question.askedBy === personId || (company !== undefined && people.get(question.askedBy)?.company === company));
	});
}

/** Activity a person may read: everything in rooms they manage, and their own actions anywhere. */
export function visibleActivity(data: DataRoomsData, personId: string) {
	return memoized(ACTIVITY_CACHE, data, personId, () => {
		const managed = new Set(data.rooms.filter((room) => can(data, personId, 'manage_room', { kind: 'room', roomId: room.id })).map((room) => room.id));
		return data.activity.filter((event) => managed.has(event.roomId) || event.actorId === personId);
	});
}

/** Whether a person must accept the room's agreement before entering. Room managers never do. */
export function needsAgreement(data: DataRoomsData, personId: string, roomId: string) {
	const room = data.rooms.find((candidate) => candidate.id === roomId);
	if (!room?.policies.requireAgreement || !room.agreement) return false;
	if (can(data, personId, 'manage_room', { kind: 'room', roomId })) return false;
	const version = room.agreement.version;
	return !data.acceptances.some((acceptance) => acceptance.roomId === roomId && acceptance.personId === personId && acceptance.version >= version);
}

/** Everyone with access to a room, or a pending invite, ordered by level then name. */
export function roomPeople(data: DataRoomsData, roomId: string) {
	return memoized(PEOPLE_CACHE, data, roomId, () => computeRoomPeople(data, roomId));
}

function computeRoomPeople(data: DataRoomsData, roomId: string) {
	const rows: { person: Person; access: EffectiveAccess }[] = [];
	for (const person of data.people) {
		const access = effectiveAccess(data, person.id, { kind: 'room', roomId });
		const pending = access.ignored.some((entry) => entry.reason === 'pending' && entry.scope?.kind === 'room' && entry.scope.id === roomId);
		if (access.grants.length || pending) rows.push({ person, access });
	}
	return rows.sort((a, b) => LEVEL_RANK[b.access.level] - LEVEL_RANK[a.access.level] || a.person.name.localeCompare(b.person.name));
}

/* ------------------------------------------------------------------ *
 * Explanations
 * ------------------------------------------------------------------ */

const LEVEL_NOUN = { owner: 'Owner', admin: 'Admin', member: 'Member' } as const;

function scopeName(data: DataRoomsData, scope: MembershipScope) {
	return scope.kind === 'room'
		? (data.rooms.find((room) => room.id === scope.id)?.name ?? 'this room')
		: (data.units.find((unit) => unit.id === scope.id)?.name ?? 'a unit');
}

/** One grant in plain words, e.g. "Admin of Northwind Holdings, carried into Fund II". */
export function describeGrant(data: DataRoomsData, grant: AccessGrant, formatDate: (iso: string) => string = (iso) => iso.slice(0, 10)) {
	if (grant.kind === 'share') {
		const what = grant.permissions.includes('delete') ? 'view, edit, and delete' : grant.permissions.includes('edit') ? 'view and edit' : 'view';
		return `Shared ${folderName(grant.folder)} to ${what}${grant.expiresAt ? ` until ${formatDate(grant.expiresAt)}` : ''}`;
	}
	const role = grant.roleId ? data.roles.find((candidate) => candidate.id === grant.roleId)?.name : undefined;
	const where = scopeName(data, grant.scope);
	const what = grant.level === 'member' ? `${role ?? 'Member'} in ${where}` : `${LEVEL_NOUN[grant.level]} of ${where}`;
	if (!grant.inherited) return grant.readOnly ? `${what}, read-only` : what;
	const below = grant.path
		.slice(1)
		.map((unitId) => data.units.find((unit) => unit.id === unitId)?.name)
		.filter(Boolean);
	const carried = below.length ? `, carried through ${below.join(' and ')}` : ', carried into its rooms';
	return `${what}${carried}${grant.readOnly ? ', read-only' : ''}`;
}

/** Why some access doesn't count, in plain words. */
export function describeIgnored(data: DataRoomsData, entry: AccessIgnored, formatDate: (iso: string) => string = (iso) => iso.slice(0, 10)) {
	const where = entry.scope ? scopeName(data, entry.scope) : 'a folder';
	const who = entry.level ? `${LEVEL_NOUN[entry.level]} of ${where}` : entry.shareId ? 'Folder share' : `Access to ${where}`;
	switch (entry.reason) {
		case 'pending':
			return `Invited to ${where}, not accepted yet`;
		case 'suspended':
			return `${who}, suspended`;
		case 'expired':
			return `${who}, expired ${entry.at ? formatDate(entry.at) : ''}`.trim();
		case 'not-inherited':
			return `${who}, but ${entry.level === 'member' ? 'members' : `${entry.level}s`} don't join sub-units and rooms automatically`;
		case 'restricted':
			return `${who}, but this room only admits people added to it`;
	}
}

'use client';

import { Activity, Download } from 'lucide-react';
import * as React from 'react';

import { formatCount, isUnsetDate } from '@/lib/intl';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { enterClass, FilterGroup, focusRingClass, staggerStyle, ViewFrame } from '@/components/ui/workspace-kit/primitives';
import { dashedRule, EmptyState, Panel } from '@/components/ui/workspace-kit/surface';
import { folderName, visibleActivity } from '@/components/ui/data-rooms/access';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { addDays, formatDuration } from '@/components/ui/data-rooms/format';
import { ChoiceSelect, PersonAvatar } from '@/components/ui/data-rooms/parts';
import type { ActivityEvent, ActivityKind } from '@/components/ui/data-rooms/types';

type Filter = 'all' | 'reading' | 'documents' | 'access' | 'questions';

const GROUPS: Record<Exclude<Filter, 'all'>, ActivityKind[]> = {
	reading: ['view', 'download'],
	documents: ['upload', 'version', 'move', 'delete'],
	access: ['share', 'unshare', 'invite', 'join', 'role', 'remove', 'agreement', 'settings'],
	questions: ['question', 'answer'],
};

const PAGE = 60;

/** Events the acting person may see, newest first. */
function useVisibleEvents() {
	const { data, actingId } = useDataRooms();
	return React.useMemo(() => [...visibleActivity(data, actingId)].sort((a, b) => b.at.localeCompare(a.at)), [actingId, data]);
}

function LinkButton({ children, onClick }: { children: React.ReactNode; onClick: () => void }) {
	return (
		<button
			type="button"
			onClick={onClick}
			className={cn('cursor-pointer rounded-sm text-start font-medium text-foreground underline-offset-4 [overflow-wrap:anywhere] hover:underline', focusRingClass)}
		>
			{children}
		</button>
	);
}

/** One event as a plain sentence, with documents and rooms you can open. */
export function ActivitySentence({ event }: { event: ActivityEvent }) {
	const { person, document: findDocument, room, openDocument, role } = useDataRooms();
	const actor = person(event.actorId)?.name ?? 'Someone';
	const subject = event.subjectId ? (person(event.subjectId)?.name ?? 'someone') : (event.detail ?? 'someone');
	const document = event.documentId ? findDocument(event.documentId) : undefined;
	const doc = document ? <LinkButton onClick={() => openDocument(document.id)}>{document.name}</LinkButton> : <span>a deleted document</span>;
	const roomName = room(event.roomId)?.name ?? 'a room';

	switch (event.kind) {
		case 'view':
			return (
				<>
					{actor} viewed {doc}
					{event.seconds ? <span className="text-muted-foreground tabular-nums"> for {formatDuration(event.seconds)}</span> : null}
				</>
			);
		case 'download':
			return (
				<>
					{actor} downloaded {doc}
				</>
			);
		case 'upload':
			return (
				<>
					{actor} uploaded {doc}
				</>
			);
		case 'version': {
			const version = document?.versions.find((entry) => entry.uploadedAt === event.at);
			return (
				<>
					{actor} uploaded {version ? `version ${version.number} of ` : 'a new version of '}
					{doc}
					{event.detail ? <span className="text-muted-foreground"> · {event.detail}</span> : null}
				</>
			);
		}
		case 'move':
			return (
				<>
					{actor} moved {doc} to {folderName(event.detail ?? '/')}
				</>
			);
		case 'delete':
			return (
				<>
					{actor} deleted {document ? doc : (event.detail ?? 'a document')}
				</>
			);
		case 'share':
			return (
				<>
					{actor} shared {folderName(event.detail ?? '/')} with {subject}
				</>
			);
		case 'unshare':
			return (
				<>
					{actor} stopped sharing {folderName(event.detail ?? '/')} with {subject}
				</>
			);
		case 'invite':
			return (
				<>
					{actor} invited {subject} to {roomName}
				</>
			);
		case 'join':
			return <>{actor} joined {roomName}</>;
		case 'role':
			return (
				<>
					{actor} changed {subject}’s access{event.detail ? ` to ${role(event.detail)?.name ?? event.detail}` : ''}
				</>
			);
		case 'remove':
			return (
				<>
					{actor} removed {subject} from {roomName}
				</>
			);
		case 'agreement':
			return (
				<>
					{actor} accepted the {room(event.roomId)?.agreement?.title.toLowerCase() ?? 'agreement'}
					{event.detail ? <span className="text-muted-foreground"> · {event.detail}</span> : null}
				</>
			);
		case 'question':
			return (
				<>
					{actor} asked “{event.detail ?? 'a question'}”{document ? <> about {doc}</> : null}
				</>
			);
		case 'answer':
			return (
				<>
					{actor} answered “{event.detail ?? 'a question'}”
				</>
			);
		case 'settings':
			return (
				<>
					{actor} updated {roomName}
					{event.detail ? <span className="text-muted-foreground"> · {event.detail}</span> : null}
				</>
			);
	}
}

/**
 * Everything that happened in the rooms the acting person manages: reading,
 * document changes, access changes, and Q&A, grouped by day.
 */
export function ActivityView() {
	const { data, emit, person, room, openRoom, format } = useDataRooms();
	const events = useVisibleEvents();
	const [filter, setFilter] = React.useState<Filter>('all');
	const [roomFilter, setRoomFilter] = React.useState('');
	const [limit, setLimit] = React.useState(PAGE);
	const roomSelectId = React.useId();

	const inRoom = roomFilter ? events.filter((event) => event.roomId === roomFilter) : events;
	const count = (key: Filter) => (key === 'all' ? inRoom.length : inRoom.filter((event) => GROUPS[key].includes(event.kind)).length);
	const filtered = filter === 'all' ? inRoom : inRoom.filter((event) => GROUPS[filter].includes(event.kind));
	const shown = filtered.slice(0, limit);
	const rooms = [...new Set(events.map((event) => event.roomId))].map((id) => room(id)).filter((entry) => entry !== undefined);

	const todayKey = format.dayKey(data.clock);
	const yesterdayKey = format.dayKey(addDays(data.clock, -1));
	const days: { key: string; label: string; events: ActivityEvent[] }[] = [];
	for (const event of shown) {
		const key = format.dayKey(event.at);
		let day = days[days.length - 1];
		if (!day || day.key !== key) {
			day = { key, label: isUnsetDate(event.at) ? 'Undated' : key === todayKey ? 'Today' : key === yesterdayKey ? 'Yesterday' : format.date(event.at), events: [] };
			days.push(day);
		}
		day.events.push(event);
	}

	return (
		<ViewFrame
			icon={Activity}
			title="Activity"
			actions={
				<Button size="xs" variant="outline" onClick={() => emit({ type: 'export-activity', roomId: roomFilter || undefined })}>
					<Download aria-hidden="true" />
					Export
				</Button>
			}
		>
			<div className="flex flex-wrap items-center gap-2">
				<FilterGroup<Filter>
					label="Activity type"
					value={filter}
					onChange={(next) => {
						setFilter(next);
						setLimit(PAGE);
					}}
					rootClassName="flex-1"
					options={[
						{ value: 'all', label: 'All', count: count('all') },
						{ value: 'reading', label: 'Reading', count: count('reading') },
						{ value: 'documents', label: 'Documents', count: count('documents') },
						{ value: 'access', label: 'Access', count: count('access') },
						{ value: 'questions', label: 'Q&A', count: count('questions') },
					]}
				/>
				<label htmlFor={roomSelectId} className="sr-only">
					Room
				</label>
				<ChoiceSelect
					id={roomSelectId}
					value={roomFilter}
					onValueChange={(next) => {
						setRoomFilter(next);
						setLimit(PAGE);
					}}
					className="w-auto min-w-40"
					options={[{ value: '', label: 'All rooms' }, ...rooms.map((entry) => ({ value: entry.id, label: entry.name }))]}
				/>
			</div>

			{days.length === 0 ? (
				<EmptyState icon={Activity} title="Nothing here yet" description="Reading, uploads, and access changes in your rooms show up here." />
			) : (
				days.map((day, dayIndex) => (
					<Panel key={day.key} title={day.label} className={enterClass} style={staggerStyle(Math.min(dayIndex, 4), 60)} bodyClassName="px-0 pb-1">
						<ul className="flex flex-col">
							{day.events.map((event, index) => (
								<li key={event.id} className={cn('flex items-start gap-3 px-4 py-2.5', index > 0 && cn('border-t', dashedRule))}>
									<PersonAvatar person={person(event.actorId)} size="sm" className="mt-px" />
									<p className="min-w-0 flex-1 text-pretty text-[0.8125rem] text-foreground [overflow-wrap:anywhere]">
										<ActivitySentence event={event} />
									</p>
									<span className="flex shrink-0 flex-col items-end gap-0.5 text-end">
										<time dateTime={event.at} className="text-xs text-muted-foreground tabular-nums">
											{format.time(event.at)}
										</time>
										<button
											type="button"
											title={room(event.roomId)?.name}
											onClick={() => openRoom(event.roomId)}
											className={cn('hidden max-w-[10rem] cursor-pointer truncate rounded-sm text-[0.6875rem] text-subtle-foreground hover:text-foreground @md/view:block', focusRingClass)}
										>
											{room(event.roomId)?.name ?? 'Room'}
										</button>
									</span>
								</li>
							))}
						</ul>
					</Panel>
				))
			)}

			{filtered.length > limit ? (
				<div className="flex justify-center">
					<Button size="sm" variant="outline" onClick={() => setLimit((current) => current + PAGE)}>
						Show more
						<span className="text-muted-foreground tabular-nums">{formatCount(filtered.length - limit)}</span>
					</Button>
				</div>
			) : null}
		</ViewFrame>
	);
}

'use client';

import { FileSignature } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { enterClass } from '@/components/ui/workspace-kit/primitives';
import { Bezel, IconTile } from '@/components/ui/workspace-kit/surface';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import type { Room } from '@/components/ui/data-rooms/types';
import { useCommand } from '@/components/ui/data-rooms/use-command';

/**
 * The room's agreement, shown in place of its content until the person
 * accepts the current version. A preview shows it too, but can't accept on
 * someone's behalf.
 */
export function AgreementGate({ room }: { room: Room }) {
	const { data, actingId, previewAs, person, setView, format } = useDataRooms();
	const command = useCommand();
	const [agreed, setAgreed] = React.useState(false);
	const checkboxId = React.useId();
	const agreement = room.agreement;
	if (!agreement) return null;

	const previous = data.acceptances
		.filter((acceptance) => acceptance.roomId === room.id && acceptance.personId === actingId)
		.sort((a, b) => b.version - a.version)[0];
	const previewing = previewAs ? person(previewAs) : undefined;

	const accept = () => void command.run({ type: 'accept-agreement', roomId: room.id, version: agreement.version });

	return (
		<div className="px-4 @3xl/view:px-6">
			<Bezel className={cn('mx-auto my-8 max-w-xl', enterClass)} innerClassName="flex flex-col">
				<header className="flex items-start gap-3 px-5 pt-5 pb-4">
					<IconTile icon={FileSignature} tone="primary" />
					<div className="min-w-0 flex-1">
						<h2 className="text-[0.9375rem] font-medium tracking-tight text-foreground">{agreement.title}</h2>
						<p className="mt-0.5 text-[0.8125rem] text-muted-foreground tabular-nums">
							Version {agreement.version}
							{agreement.updatedAt ? ` · updated ${format.date(agreement.updatedAt)}` : ''}
						</p>
					</div>
				</header>
				{previous && previous.version < agreement.version ? (
					<p role="note" className="mx-5 mb-3 rounded-lg bg-warning/10 px-3 py-2 text-[0.8125rem] text-foreground">
						The agreement changed since you accepted version {previous.version}. Accept the new version to keep reading.
					</p>
				) : null}
				<div
					tabIndex={0}
					aria-label={`${agreement.title}, full text`}
					className="mx-5 max-h-[50vh] overflow-y-auto rounded-lg border border-border bg-muted/40 px-4 py-3 text-[0.8125rem] leading-6 whitespace-pre-line text-pretty text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 [mask-image:linear-gradient(to_bottom,transparent,black_12px,black_calc(100%-16px),transparent)]"
				>
					{agreement.body}
				</div>
				<div className="flex flex-col gap-3 px-5 pt-4 pb-5">
					<label htmlFor={checkboxId} className="flex cursor-pointer items-start gap-2.5 text-[0.8125rem] text-foreground">
						<Checkbox id={checkboxId} checked={agreed} onCheckedChange={(checked) => setAgreed(checked === true)} disabled={command.locked} className="mt-0.5" />
						I have read and agree to these terms
					</label>
					{previewing ? (
						<p className="text-[0.8125rem] text-muted-foreground">
							{previewing.name} sees this before entering. A preview can’t accept on their behalf.
						</p>
					) : null}
					{command.error ? (
						<p role="alert" className="text-[0.8125rem] text-destructive">
							{command.error}
						</p>
					) : null}
					<div className="flex items-center justify-end gap-2">
						<Button size="sm" variant="ghost" onClick={() => setView('home')}>
							Leave room
						</Button>
						<Button size="sm" disabled={!agreed || command.pending || command.locked} aria-busy={command.pending || undefined} onClick={accept}>
							{command.pending ? 'Accepting…' : 'Accept and enter'}
						</Button>
					</div>
				</div>
			</Bezel>
		</div>
	);
}

import { visibleDocuments } from '@/components/ui/data-rooms/access';
import type { AssistantAnswer, AssistantRequest, DataRoomsData } from '@/components/ui/data-rooms/types';

/**
 * Answers from the scripted replies, the way a retrieval-backed assistant
 * should: it only cites documents the person can open in the room, and if
 * none of a reply's sources are open to them it says it found nothing rather
 * than leaking the answer.
 */
export function answerFromScript(data: DataRoomsData, request: AssistantRequest): AssistantAnswer {
	const script = data.assistant;
	const fallback = { text: script?.fallback ?? 'I couldn’t find that in the documents you can open in this room.', citations: [] };
	if (!script) return fallback;
	const prompt = request.prompt.toLowerCase();
	const open = new Set(visibleDocuments(data, request.viewerId, request.roomId).map((document) => document.id));
	const scored = script.replies
		.map((reply) => ({ reply, score: reply.match.filter((word) => prompt.includes(word.toLowerCase())).length }))
		.filter((entry) => entry.score > 0)
		.sort((a, b) => b.score - a.score);
	for (const { reply } of scored) {
		const citations = reply.citations.filter((citation) => open.has(citation.documentId));
		if (citations.length) return { text: reply.text, citations };
	}
	return fallback;
}

import { normalizeFolder } from '@/components/ui/data-rooms/access';
import type { ActivityEvent, DataRoomsCommand, DataRoomsData, Person } from '@/components/ui/data-rooms/types';

export type CommandContext = {
	/** Who is making the change. */
	actorId: string;
	/** When the change happens. */
	now: string;
	/** Makes ids for rows the change creates. */
	id: (prefix: string) => string;
};

/** A counter-based id maker, stable across renders and fine for local, optimistic rows. */
export function createIdMaker(seed = 'local') {
	let next = 0;
	return (prefix: string) => `${seed}-${prefix}-${++next}`;
}

/**
 * Applies a command to the data the template renders, the way a host would
 * after its API accepts the change. The template uses it for optimistic
 * updates; hosts can use it too, then replace the result with fresh data.
 */
export function applyDataRoomsCommand(data: DataRoomsData, command: DataRoomsCommand, context: CommandContext): DataRoomsData {
	const { actorId, now, id } = context;
	const log = (event: Omit<ActivityEvent, 'id' | 'at' | 'actorId'>): ActivityEvent => ({ id: id('event'), at: now, actorId, ...event });

	switch (command.type) {
		case 'create-room':
			return {
				...data,
				rooms: [...data.rooms, command.room],
				memberships: [
					...data.memberships,
					{ id: id('membership'), personId: actorId, scope: { kind: 'room', id: command.room.id }, owner: true, status: 'active', joinedAt: now },
				],
				activity: [...data.activity, log({ kind: 'settings', roomId: command.room.id, detail: 'Created the room' })],
			};
		case 'update-room':
			return {
				...data,
				rooms: data.rooms.map((room) => (room.id === command.roomId ? { ...room, ...command.patch } : room)),
				activity: [...data.activity, log({ kind: 'settings', roomId: command.roomId, detail: Object.keys(command.patch).join(', ') })],
			};
		case 'invite': {
			const people: Person[] = [...data.people];
			const memberships = [...data.memberships];
			const invites = [...data.invites];
			const activity = [...data.activity];
			for (const entry of command.invites) {
				const known = entry.personId
					? people.find((person) => person.id === entry.personId)
					: people.find((person) => person.email.toLowerCase() === entry.email.toLowerCase());
				if (known) {
					const existing = memberships.find((membership) => membership.personId === known.id && membership.scope.kind === 'room' && membership.scope.id === command.roomId);
					if (existing) continue;
					memberships.push({
						id: id('membership'),
						personId: known.id,
						scope: { kind: 'room', id: command.roomId },
						roleId: command.roleId,
						status: 'active',
						expiresAt: command.expiresAt,
						invitedBy: actorId,
						joinedAt: now,
					});
					activity.push(log({ kind: 'invite', roomId: command.roomId, subjectId: known.id }));
				} else {
					invites.push({ id: id('invite'), roomId: command.roomId, email: entry.email, roleId: command.roleId, invitedBy: actorId, invitedAt: now, expiresAt: command.expiresAt });
					activity.push(log({ kind: 'invite', roomId: command.roomId, detail: entry.email }));
				}
			}
			return { ...data, people, memberships, invites, activity };
		}
		case 'revoke-invite':
			return { ...data, invites: data.invites.filter((invite) => invite.id !== command.inviteId) };
		case 'update-membership': {
			const membership = data.memberships.find((candidate) => candidate.id === command.membershipId);
			return {
				...data,
				memberships: data.memberships.map((candidate) => (candidate.id === command.membershipId ? { ...candidate, ...command.patch } : candidate)),
				activity:
					membership?.scope.kind === 'room'
						? [...data.activity, log({ kind: 'role', roomId: membership.scope.id, subjectId: membership.personId })]
						: data.activity,
			};
		}
		case 'remove-membership': {
			const membership = data.memberships.find((candidate) => candidate.id === command.membershipId);
			return {
				...data,
				memberships: data.memberships.filter((candidate) => candidate.id !== command.membershipId),
				activity:
					membership?.scope.kind === 'room'
						? [...data.activity, log({ kind: 'remove', roomId: membership.scope.id, subjectId: membership.personId })]
						: data.activity,
			};
		}
		case 'create-share': {
			const folder = normalizeFolder(command.folder);
			const shares = data.shares.filter(
				(share) => !(share.roomId === command.roomId && share.folder === folder && command.personIds.includes(share.personId)),
			);
			for (const personId of command.personIds) {
				shares.push({ id: id('share'), roomId: command.roomId, folder, personId, can: command.can, expiresAt: command.expiresAt, createdBy: actorId, createdAt: now });
			}
			return {
				...data,
				shares,
				activity: [...data.activity, ...command.personIds.map((personId) => log({ kind: 'share', roomId: command.roomId, subjectId: personId, detail: folder }))],
			};
		}
		case 'revoke-share': {
			const share = data.shares.find((candidate) => candidate.id === command.shareId);
			return {
				...data,
				shares: data.shares.filter((candidate) => candidate.id !== command.shareId),
				activity: share ? [...data.activity, log({ kind: 'unshare', roomId: share.roomId, subjectId: share.personId, detail: share.folder })] : data.activity,
			};
		}
		case 'upload': {
			const folder = normalizeFolder(command.folder);
			const documents = command.files.map((file) => {
				const documentId = id('document');
				return {
					id: documentId,
					roomId: command.roomId,
					folder,
					name: file.name,
					kind: file.kind,
					size: file.size,
					pages: file.pages,
					versions: [{ id: id('version'), number: 1, uploadedBy: actorId, uploadedAt: now, size: file.size }],
					uploadedBy: actorId,
					updatedAt: now,
					status: 'processing' as const,
				};
			});
			return {
				...data,
				documents: [...data.documents, ...documents],
				activity: [...data.activity, ...documents.map((document) => log({ kind: 'upload', roomId: command.roomId, documentId: document.id }))],
			};
		}
		case 'create-folder':
			return { ...data, folders: [...(data.folders ?? []), { roomId: command.roomId, path: normalizeFolder(command.path) }] };
		case 'move-documents': {
			const folder = normalizeFolder(command.folder);
			const moved = data.documents.filter((document) => command.documentIds.includes(document.id));
			return {
				...data,
				documents: data.documents.map((document) => (command.documentIds.includes(document.id) ? { ...document, folder, updatedAt: now } : document)),
				activity: [...data.activity, ...moved.map((document) => log({ kind: 'move', roomId: document.roomId, documentId: document.id, detail: folder }))],
			};
		}
		case 'update-document':
			return {
				...data,
				documents: data.documents.map((document) => (document.id === command.documentId ? { ...document, ...command.patch } : document)),
			};
		case 'update-inheritance':
			return { ...data, inheritance: command.inheritance };
		case 'save-role':
			return {
				...data,
				roles: data.roles.some((role) => role.id === command.role.id)
					? data.roles.map((role) => (role.id === command.role.id ? command.role : role))
					: [...data.roles, command.role],
			};
		case 'accept-agreement':
			return {
				...data,
				acceptances: [...data.acceptances, { roomId: command.roomId, personId: actorId, version: command.version, acceptedAt: now }],
				activity: [...data.activity, log({ kind: 'agreement', roomId: command.roomId, detail: `Version ${command.version}` })],
			};
		case 'ask-question': {
			const questionId = id('question');
			return {
				...data,
				questions: [
					...data.questions,
					{
						id: questionId,
						roomId: command.roomId,
						documentId: command.documentId,
						askedBy: actorId,
						askedAt: now,
						title: command.title,
						status: 'open',
						messages: [{ id: id('message'), authorId: actorId, at: now, body: command.body }],
					},
				],
				activity: [...data.activity, log({ kind: 'question', roomId: command.roomId, documentId: command.documentId, detail: command.title })],
			};
		}
		case 'answer-question': {
			const question = data.questions.find((candidate) => candidate.id === command.questionId);
			return {
				...data,
				questions: data.questions.map((candidate) =>
					candidate.id === command.questionId
						? {
								...candidate,
								status: command.close ? 'closed' : 'answered',
								draft: undefined,
								messages: [...candidate.messages, { id: id('message'), authorId: actorId, at: now, body: command.body }],
							}
						: candidate,
				),
				activity: question ? [...data.activity, log({ kind: 'answer', roomId: question.roomId, documentId: question.documentId, detail: question.title })] : data.activity,
			};
		}
		case 'set-question-status':
			return {
				...data,
				questions: data.questions.map((question) => (question.id === command.questionId ? { ...question, status: command.status } : question)),
			};
	}
}

/** Marks freshly uploaded documents as ready once the host has indexed them. */
export function markDocumentsReady(data: DataRoomsData, documentIds: string[]): DataRoomsData {
	return {
		...data,
		documents: data.documents.map((document) => (documentIds.includes(document.id) ? { ...document, status: 'ready' } : document)),
	};
}

'use client';

import * as React from 'react';

import type { AccessTarget, EffectiveAccess } from '@/components/ui/data-rooms/access';
import type {
	AssistantAnswer,
	DataRoomDocument,
	DataRoomsAction,
	DataRoomsCommand,
	DataRoomsData,
	DataRoomsTheme,
	DataRoomsView,
	OrgUnit,
	Permission,
	Person,
	Role,
	Room,
	RoomTab,
} from '@/components/ui/data-rooms/types';

export type DataRoomsFormat = {
	date: (iso: string, withTime?: boolean) => string;
	/** "3:40 PM" in the template's locale and time zone. */
	time: (iso: string) => string;
	/** `YYYY-MM-DD` in the template's time zone, for grouping by day. */
	dayKey: (iso: string) => string;
	relative: (iso: string) => string;
	deadline: (iso: string) => string;
	bytes: (bytes: number) => string;
	count: (value: number) => string;
	/** Orders two names in the template's locale, with numbers by value ("Exhibit 2" before "Exhibit 10"). */
	compare: (left: string, right: string) => number;
};

export type ShareRequest = { roomId: string; folder?: string; personId?: string };

export type PreviewRenderContext = {
	/** The person reading, whose name and email a watermark should carry. */
	viewer: Person;
	watermark: boolean;
	viewOnly: boolean;
};

export type DataRoomsContextValue = {
	/** Host data with local changes applied. */
	data: DataRoomsData;
	/** The signed-in person. */
	viewerId: string;
	/** Who the workspace is shown as: the previewed person, or the viewer. */
	actingId: string;
	previewAs: string | null;
	setPreviewAs: (personId: string | null) => void;
	view: DataRoomsView;
	setView: (view: DataRoomsView) => void;
	views: DataRoomsView[];
	roomId: string | null;
	tab: RoomTab;
	setTab: (tab: RoomTab) => void;
	openRoom: (roomId: string, tab?: RoomTab) => void;
	/** Sends a change to the host, then applies it locally. Rejects with the host's error. */
	run: (command: DataRoomsCommand) => Promise<void>;
	emit: (action: DataRoomsAction) => void;
	theme: DataRoomsTheme;
	setTheme: (theme: DataRoomsTheme) => void;
	format: DataRoomsFormat;
	person: (id: string) => Person | undefined;
	unit: (id: string) => OrgUnit | undefined;
	room: (id: string) => Room | undefined;
	role: (id: string | undefined) => Role | undefined;
	document: (id: string) => DataRoomDocument | undefined;
	/** Access for the acting person, or for `personId`. */
	access: (target: AccessTarget, personId?: string) => EffectiveAccess;
	can: (permission: Permission, target: AccessTarget, personId?: string) => boolean;
	/** True when the acting person manages people or settings somewhere: admins, owners, room managers. */
	isManager: boolean;
	documentId: string | null;
	openDocument: (documentId: string | null) => void;
	openTrace: (personId: string, roomId: string) => void;
	openInvite: (roomId: string) => void;
	openShare: (request: ShareRequest) => void;
	openNewRoom: (unitId?: string) => void;
	assistantOpen: boolean;
	setAssistantOpen: (open: boolean) => void;
	/** Opens the assistant and asks it something, optionally about one document. */
	askAssistant: (prompt: string, documentId?: string) => void;
	/** A pending prompt for the assistant panel to send, set by `askAssistant`. */
	assistantPrompt: { prompt: string; documentId?: string; key: number } | null;
	answerAssistant: (prompt: string, roomId: string, documentId?: string) => Promise<AssistantAnswer>;
	renderPreview?: (document: DataRoomDocument, context: PreviewRenderContext) => React.ReactNode;
};

const DataRoomsContext = React.createContext<DataRoomsContextValue | null>(null);

function useDataRooms() {
	const context = React.useContext(DataRoomsContext);
	if (!context) throw new Error('Data Rooms parts must be rendered inside <DataRooms>.');
	return context;
}

export { DataRoomsContext, useDataRooms };

'use client';

import * as React from 'react';

import { useControllableState } from '@/hooks/use-controllable-state';
import { WorkspaceShell } from '@/components/ui/workspace-kit/shell';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { type AccessTarget, effectiveAccess, managesAnything } from '@/components/ui/data-rooms/access';
import { AccessMapView } from '@/components/ui/data-rooms/access-map-view';
import { AccessTraceSheet } from '@/components/ui/data-rooms/access-trace-sheet';
import { ActivityView } from '@/components/ui/data-rooms/activity-view';
import { answerFromScript } from '@/components/ui/data-rooms/assistant';
import { applyDataRoomsCommand, createIdMaker, markDocumentsReady } from '@/components/ui/data-rooms/commands';
import {
	DataRoomsContext,
	type DataRoomsContextValue,
	type DataRoomsFormat,
	type PreviewRenderContext,
	type ShareRequest,
} from '@/components/ui/data-rooms/data-rooms-context';
import { DocumentSheet } from '@/components/ui/data-rooms/document-sheet';
import { dayKey, formatBytes, formatCount, formatDate, formatDeadline, formatRelative, formatTime } from '@/components/ui/data-rooms/format';
import { HomeView } from '@/components/ui/data-rooms/home-view';
import { InviteDialog } from '@/components/ui/data-rooms/invite-dialog';
import { NewRoomDialog } from '@/components/ui/data-rooms/new-room-dialog';
import { RoomView } from '@/components/ui/data-rooms/room-view';
import { DataRoomsSidebar } from '@/components/ui/data-rooms/sidebar';
import { ShareDialog } from '@/components/ui/data-rooms/share-dialog';
import type {
	AssistantAnswer,
	AssistantRequest,
	DataRoomDocument,
	DataRoomsAction,
	DataRoomsCommand,
	DataRoomsData,
	DataRoomsTheme,
	DataRoomsView,
	RoomTab,
} from '@/components/ui/data-rooms/types';

const ALL_VIEWS: DataRoomsView[] = ['home', 'access-map', 'activity', 'room'];

/** How long a fresh upload shows as processing before the demo marks it ready. */
const PROCESSING_MS = 1800;

type DataRoomsProps = {
	data: DataRoomsData;
	/** Controlled view. Pair with `onViewChange` to sync with a router. */
	view?: DataRoomsView;
	defaultView?: DataRoomsView;
	onViewChange?: (view: DataRoomsView) => void;
	/** Controlled open room. */
	roomId?: string | null;
	defaultRoomId?: string | null;
	onRoomChange?: (roomId: string | null) => void;
	tab?: RoomTab;
	defaultTab?: RoomTab;
	onTabChange?: (tab: RoomTab) => void;
	/** Shows the workspace as another person sees it. Only people who manage a room can preview. */
	previewAs?: string | null;
	defaultPreviewAs?: string | null;
	onPreviewAsChange?: (personId: string | null) => void;
	/** Views the host can back. Defaults to all of them. */
	views?: DataRoomsView[];
	/**
	 * Makes a change: create a room, invite, share a folder, upload, answer a
	 * question. Resolve once it's saved and the template applies it locally;
	 * reject with an Error to keep the dialog open with its message.
	 */
	onCommand?: (command: DataRoomsCommand) => Promise<void> | void;
	/** Receives every control the template renders but does not own. */
	onAction?: (action: DataRoomsAction) => void;
	/** Answers the room assistant. Without it, answers come from `data.assistant`. */
	onAskAssistant?: (request: AssistantRequest) => Promise<AssistantAnswer>;
	/** Renders a document's pages in the viewer. Without it, the viewer draws placeholder pages. */
	renderPreview?: (document: DataRoomDocument, context: PreviewRenderContext) => React.ReactNode;
	theme?: DataRoomsTheme;
	onThemeChange?: (theme: DataRoomsTheme) => void;
	defaultSidebarCollapsed?: boolean;
	/** Shows the workspace as a rounded frame on a canvas instead of filling its container. */
	framed?: boolean;
	/** Formatting for dates and numbers. Defaults to `en-US` in UTC, so server and client agree. */
	locale?: string;
	timeZone?: string;
	className?: string;
};

/**
 * Data Rooms template: secure rooms owned by an organization and its
 * sub-organizations. Access carries down the hierarchy, folders can be shared
 * with guests, agreements gate entry, and every room has Q&A, insights, and an
 * assistant that only cites what the reader can open. Every collection comes
 * from `data`; every change goes through `onCommand`.
 */
function DataRooms({
	data,
	view: viewProp,
	defaultView = 'home',
	onViewChange,
	roomId: roomIdProp,
	defaultRoomId = null,
	onRoomChange,
	tab: tabProp,
	defaultTab = 'documents',
	onTabChange,
	previewAs: previewProp,
	defaultPreviewAs = null,
	onPreviewAsChange,
	views = ALL_VIEWS,
	onCommand,
	onAction,
	onAskAssistant,
	renderPreview,
	theme: themeProp,
	onThemeChange,
	defaultSidebarCollapsed = false,
	framed,
	locale = 'en-US',
	timeZone = 'UTC',
	className,
}: DataRoomsProps) {
	const [requestedView, setView] = useControllableState<DataRoomsView>({ prop: viewProp, defaultProp: defaultView, onChange: onViewChange });
	const [roomId, setRoomId] = useControllableState<string | null>({ prop: roomIdProp, defaultProp: defaultRoomId, onChange: onRoomChange });
	const [tab, setTab] = useControllableState<RoomTab>({ prop: tabProp, defaultProp: defaultTab, onChange: onTabChange });
	const [previewAs, setPreviewAs] = useControllableState<string | null>({ prop: previewProp, defaultProp: defaultPreviewAs, onChange: onPreviewAsChange });
	const [theme, setTheme] = useControllableState<DataRoomsTheme>({ prop: themeProp, defaultProp: 'system', onChange: onThemeChange });

	// Local changes layer over host data until the host sends new data.
	const [local, setLocal] = React.useState(data);
	const [source, setSource] = React.useState(data);
	if (source !== data) {
		setSource(data);
		setLocal(data);
	}

	const [documentId, setDocumentId] = React.useState<string | null>(null);
	const [trace, setTrace] = React.useState<{ personId: string; roomId: string } | null>(null);
	const [invite, setInvite] = React.useState<{ open: boolean; roomId: string | null }>({ open: false, roomId: null });
	const [share, setShare] = React.useState<{ open: boolean; request: ShareRequest | null }>({ open: false, request: null });
	const [newRoom, setNewRoom] = React.useState<{ open: boolean; unitId?: string }>({ open: false });
	const [assistantOpen, setAssistantOpen] = React.useState(false);
	const [assistantPrompt, setAssistantPrompt] = React.useState<DataRoomsContextValue['assistantPrompt']>(null);

	const onActionRef = useLatest(onAction);
	const onCommandRef = useLatest(onCommand);
	const onAskRef = useLatest(onAskAssistant);
	const makeId = React.useRef(createIdMaker('local')).current;
	const tick = React.useRef(0);
	const timers = React.useRef(new Set<number>());
	React.useEffect(() => {
		const pending = timers.current;
		return () => {
			for (const timer of pending) window.clearTimeout(timer);
			pending.clear();
		};
	}, []);

	const actingId = previewAs ?? local.viewerId;
	const room = local.rooms.find((candidate) => candidate.id === roomId);
	const view: DataRoomsView = requestedView === 'room' && !room ? 'home' : views.includes(requestedView) ? requestedView : (views[0] ?? 'home');

	// One collator per locale: a comparator that builds its own for every pair is the slowest part of sorting a long list.
	const collator = React.useMemo(() => new Intl.Collator(locale, { numeric: true }), [locale]);
	const format = React.useMemo<DataRoomsFormat>(() => {
		const options = { locale, timeZone, now: local.clock };
		return {
			date: (iso, withTime) => formatDate(iso, options, withTime),
			time: (iso) => formatTime(iso, options),
			dayKey: (iso) => dayKey(iso, timeZone),
			relative: (iso) => formatRelative(iso, options),
			deadline: (iso) => formatDeadline(iso, options),
			bytes: (bytes) => formatBytes(bytes, locale),
			count: (value) => formatCount(value, locale),
			compare: (left, right) => collator.compare(left, right),
		};
	}, [collator, local.clock, locale, timeZone]);

	const context = React.useMemo<DataRoomsContextValue>(() => {
		const emit = (action: DataRoomsAction) => onActionRef.current?.(action);
		const byId = <T extends { id: string }>(rows: T[]) => {
			const map = new Map(rows.map((row) => [row.id, row]));
			return (id: string | undefined) => (id ? map.get(id) : undefined);
		};
		const people = byId(local.people);
		const units = byId(local.units);
		const rooms = byId(local.rooms);
		const roles = byId(local.roles);
		const documents = byId(local.documents);
		const access = (target: AccessTarget, personId = actingId) => effectiveAccess(local, personId, target);
		const isManager = managesAnything(local, actingId);

		const run = async (command: DataRoomsCommand) => {
			if (previewAs) {
				const name = people(previewAs)?.name ?? 'someone else';
				throw new Error(`You’re previewing as ${name}. Exit the preview to make changes.`);
			}
			await onCommandRef.current?.(command);
			tick.current += 1;
			const now = new Date(Date.parse(local.clock) + tick.current * 1000).toISOString();
			setLocal((current) => applyDataRoomsCommand(current, command, { actorId: current.viewerId, now, id: makeId }));
			if (command.type === 'upload') {
				// Fresh uploads index for a moment, then become searchable.
				const timer = window.setTimeout(() => {
					timers.current.delete(timer);
					setLocal((current) => {
						const pending = current.documents.filter((document) => document.status === 'processing').map((document) => document.id);
						return pending.length ? markDocumentsReady(current, pending) : current;
					});
				}, PROCESSING_MS);
				timers.current.add(timer);
			}
		};

		return {
			data: local,
			viewerId: local.viewerId,
			actingId,
			previewAs,
			setPreviewAs: (personId) => setPreviewAs(personId === local.viewerId ? null : personId),
			view,
			setView,
			views,
			roomId: room?.id ?? null,
			tab,
			setTab,
			openRoom: (id, nextTab) => {
				setRoomId(id);
				if (nextTab) setTab(nextTab);
				setView('room');
			},
			run,
			emit,
			theme,
			setTheme,
			format,
			person: people,
			unit: units,
			room: rooms,
			role: roles,
			document: documents,
			access,
			can: (permission, target, personId) => access(target, personId).permissions.includes(permission),
			isManager,
			documentId,
			openDocument: (id) => {
				setDocumentId(id);
				if (id) emit({ type: 'view-document', documentId: id });
			},
			openTrace: (personId, traceRoomId) => setTrace({ personId, roomId: traceRoomId }),
			openInvite: (inviteRoomId) => setInvite({ open: true, roomId: inviteRoomId }),
			openShare: (request) => setShare({ open: true, request }),
			openNewRoom: (unitId) => setNewRoom({ open: true, unitId }),
			assistantOpen,
			setAssistantOpen,
			askAssistant: (prompt, aboutDocumentId) => {
				setAssistantOpen(true);
				setAssistantPrompt((current) => ({ prompt, documentId: aboutDocumentId, key: (current?.key ?? 0) + 1 }));
			},
			assistantPrompt,
			answerAssistant: (prompt, answerRoomId, aboutDocumentId) => {
				const request: AssistantRequest = { roomId: answerRoomId, prompt, viewerId: actingId, documentId: aboutDocumentId };
				return onAskRef.current ? onAskRef.current(request) : Promise.resolve(answerFromScript(local, request));
			},
			renderPreview,
		};
	}, [
		actingId,
		assistantOpen,
		assistantPrompt,
		documentId,
		format,
		local,
		makeId,
		onActionRef,
		onAskRef,
		onCommandRef,
		previewAs,
		renderPreview,
		room?.id,
		setPreviewAs,
		setRoomId,
		setTab,
		setTheme,
		setView,
		tab,
		theme,
		view,
		views,
	]);

	return (
		<DataRoomsContext.Provider value={context}>
			<WorkspaceShell
				slot="data-rooms"
				className={className}
				defaultSidebarCollapsed={defaultSidebarCollapsed}
				framed={framed}
				sidebar={({ mode, collapsed, onCollapsedChange, onNavigate }) => (
					<DataRoomsSidebar
						drawer={mode === 'drawer'}
						collapsed={collapsed}
						onCollapsedChange={onCollapsedChange}
						onNavigate={mode === 'drawer' ? onNavigate : undefined}
					/>
				)}
			>
				{view === 'home' ? <HomeView /> : null}
				{view === 'access-map' ? <AccessMapView /> : null}
				{view === 'activity' ? <ActivityView /> : null}
				{view === 'room' && room ? <RoomView key={room.id} room={room} /> : null}
			</WorkspaceShell>
			<DocumentSheet />
			<AccessTraceSheet request={trace} onOpenChange={(open) => {
					if (!open) setTrace(null);
				}} />
			<InviteDialog roomId={invite.roomId} open={invite.open} onOpenChange={(open) => setInvite((current) => ({ ...current, open }))} />
			<ShareDialog request={share.request} open={share.open} onOpenChange={(open) => setShare((current) => ({ ...current, open }))} />
			<NewRoomDialog unitId={newRoom.unitId} open={newRoom.open} onOpenChange={(open) => setNewRoom((current) => ({ ...current, open }))} />
		</DataRoomsContext.Provider>
	);
}

