import type { DataRoomDocument } from '@/components/ui/data-rooms/types';

/** What the room root is called in the tree, breadcrumb, and pickers. */
export const ROOT_LABEL = 'All documents';

/** Indentation stops growing here, so a deeply nested folder still has room for its name. */
const MAX_INDENT_LEVELS = 5;

/** Immediate child folders of `folder` among `folders`. */
export function childFolders(folders: readonly string[], folder: string) {
	return folders.filter((candidate) => candidate !== folder && parentFolder(candidate) === normalizeFolder(folder));
}

function depthOf(path: string) {
	const normalized = normalizeFolder(path);
	return normalized === '/' ? 0 : normalized.split('/').length - 1;
}

type FolderNode = { path: string; depth: number; count: number };

type FolderTreeProps = {
	/** Folders to show, root included. */
	folders: readonly string[];
	/** Documents the person can open, counted under each folder. */
	documents: readonly DataRoomDocument[];
	/** The open folder. */
	current: string;
	/** True while a search replaces the folder view, so no folder reads as open. */
	searching: boolean;
	onSelect: (path: string) => void;
	/** A quiet note under the tree. */
	note?: React.ReactNode;
};

/**
 * The room's folders as a collapsible tree. Counts stay faint and show on
 * hover, or for the open folder, so the tree reads as navigation.
 */
export function FolderTree({ folders, documents, current, searching, onSelect, note }: FolderTreeProps) {
	const [collapsed, setCollapsed] = React.useState<ReadonlySet<string>>(() => new Set());
	const open = normalizeFolder(current);

	const tree = React.useMemo<FolderNode[]>(() => {
		const nodes: FolderNode[] = [];
		const visit = (path: string) => {
			nodes.push({ path, depth: depthOf(path), count: documents.filter((document) => folderContains(path, document.folder)).length });
			if (collapsed.has(path)) return;
			for (const child of childFolders(folders, path)) visit(child);
		};
		visit('/');
		return nodes;
	}, [collapsed, documents, folders]);

	const toggle = (path: string) =>
		setCollapsed((previous) => {
			const next = new Set(previous);
			if (next.has(path)) next.delete(path);
			else next.add(path);
			return next;
		});

	return (
		<nav aria-label="Folders" className="hidden w-60 shrink-0 flex-col gap-0.5 overflow-y-auto border-e border-border p-2 @3xl/view:flex">
			<ul className="flex flex-col gap-0.5">
				{tree.map((node) => {
					const active = node.path === open && !searching;
					const expanded = !collapsed.has(node.path);
					return (
						<li key={node.path} className="flex items-center" style={{ paddingInlineStart: Math.min(node.depth, MAX_INDENT_LEVELS) * 12 }}>
							{childFolders(folders, node.path).length > 0 ? (
								<button
									type="button"
									aria-label={`${expanded ? 'Collapse' : 'Expand'} ${folderName(node.path, ROOT_LABEL)}`}
									aria-expanded={expanded}
									onClick={() => toggle(node.path)}
									className={cn('grid size-6 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground hover:bg-overlay-hover hover:text-foreground', focusRingClass)}
								>
									<ChevronRight aria-hidden="true" className={cn('size-3.5 transition-transform duration-(--duration-fast) motion-reduce:transition-none', expanded ? 'rotate-90' : 'rtl:-scale-x-100')} />
								</button>
							) : (
								<span aria-hidden="true" className="size-6 shrink-0" />
							)}
							<button
								type="button"
								aria-current={active ? 'true' : undefined}
								onClick={() => onSelect(node.path)}
								className={cn(
									'group/folder flex h-7 min-w-0 flex-1 cursor-pointer items-center gap-2 rounded-md px-1.5 text-start text-[0.8125rem]',
									focusRingClass,
									active ? 'bg-sidebar-accent font-medium text-foreground' : 'text-foreground/90 hover:bg-overlay-hover',
								)}
							>
								{active ? (
									<FolderOpen aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
								) : (
									<FolderClosed aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
								)}
								<span title={folderName(node.path, ROOT_LABEL)} className="min-w-0 flex-1 truncate">
									{folderName(node.path, ROOT_LABEL)}
								</span>
								<span className={cn('shrink-0 text-xs text-subtle-foreground tabular-nums', !active && 'opacity-0 group-hover/folder:opacity-100 group-focus-visible/folder:opacity-100')}>
									{formatCount(node.count)}
								</span>
							</button>
						</li>
					);
				})}
			</ul>
			{note ? <p className="mt-2 px-2 text-xs text-pretty text-subtle-foreground">{note}</p> : null}
		</nav>
	);
}

import { initials as initialsOf } from '@/lib/initials';
import { dateFormat, isUnsetDate, numberFormat } from '@/lib/intl';
import type { DocumentKind } from '@/components/ui/data-rooms/types';

export type DataRoomsFormatOptions = { locale: string; timeZone: string; now: string };

export const DAY_MS = 86_400_000;
const DAY = DAY_MS;

/** `iso` moved by whole days; negative days go back. */
export function addDays(iso: string, days: number) {
	return new Date(Date.parse(iso) + days * DAY_MS).toISOString();
}


/** "Sep 24", or "Sep 24, 2025" outside the current year. A date nobody set is a dash. */
export function formatDate(iso: string, { locale, timeZone, now }: DataRoomsFormatOptions, withTime = false) {
	if (isUnsetDate(iso)) return '—';
	const date = new Date(iso);
	const sameYear = new Date(now).getUTCFullYear() === date.getUTCFullYear();
	return dateFormat(locale, {
		month: 'short',
		day: 'numeric',
		year: sameYear ? undefined : 'numeric',
		hour: withTime ? 'numeric' : undefined,
		minute: withTime ? '2-digit' : undefined,
		timeZone,
	}).format(date);
}

export function formatTime(iso: string, { locale, timeZone }: DataRoomsFormatOptions) {
	if (isUnsetDate(iso)) return '—';
	return dateFormat(locale, { hour: 'numeric', minute: '2-digit', timeZone }).format(new Date(iso));
}

/** `YYYY-MM-DD` for the day `iso` falls on in `timeZone`; empty for a date nobody set, so those group together. */
export function dayKey(iso: string, timeZone: string) {
	if (isUnsetDate(iso)) return '';
	return dateFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(iso));
}

/** "just now", "12 min ago", "3 h ago", "yesterday", "4 days ago", then a date; "in 12 min", "tomorrow" and so on for a time ahead. */
export function formatRelative(iso: string, options: DataRoomsFormatOptions) {
	if (isUnsetDate(iso)) return '—';
	const diff = Date.parse(options.now) - Date.parse(iso);
	if (diff < 0 && -diff >= 60_000) {
		const ahead = -diff;
		if (ahead < 3_600_000) return `in ${Math.floor(ahead / 60_000)} min`;
		if (ahead < DAY) return `in ${Math.floor(ahead / 3_600_000)} h`;
		if (ahead < 2 * DAY) return 'tomorrow';
		if (ahead < 7 * DAY) return `in ${Math.floor(ahead / DAY)} days`;
		return formatDate(iso, options);
	}
	if (diff < 60_000) return 'just now';
	if (diff < 3_600_000) return `${Math.floor(diff / 60_000)} min ago`;
	if (diff < DAY) return `${Math.floor(diff / 3_600_000)} h ago`;
	if (diff < 2 * DAY) return 'yesterday';
	if (diff < 7 * DAY) return `${Math.floor(diff / DAY)} days ago`;
	return formatDate(iso, options);
}

/** Whole days from `now` until `iso`, to the nearest day; negative once it has passed. */
export function daysUntil(iso: string, now: string) {
	const days = (Date.parse(iso) - Date.parse(now)) / DAY;
	return days < 0 ? Math.floor(days) : Math.round(days);
}

/** "in 3 days", "tomorrow", "today", or "ended Sep 2"; a dash when there is no deadline. */
export function formatDeadline(iso: string, options: DataRoomsFormatOptions) {
	if (isUnsetDate(iso)) return '—';
	const days = daysUntil(iso, options.now);
	if (days < 0) return `ended ${formatDate(iso, options)}`;
	if (days === 0) return 'today';
	if (days === 1) return 'tomorrow';
	if (days <= 14) return `in ${days} days`;
	return formatDate(iso, options);
}

export function formatBytes(bytes: number, locale = 'en-US') {
	const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
	let value = bytes;
	let unit = 0;
	// Compare the rounded value: 1,048,500 bytes is 1,023.9 KB, which would print as "1,024 KB" instead of "1 MB".
	while (Math.round(value) >= 1024 && unit < units.length - 1) {
		value /= 1024;
		unit += 1;
	}
	return `${numberFormat(locale, { maximumFractionDigits: value < 10 && unit > 0 ? 1 : 0 }).format(value)} ${units[unit]}`;
}

/** "4m 20s", "45s", "1h 05m" for time spent reading. */
export function formatDuration(seconds: number) {
	if (seconds < 60) return `${Math.round(seconds)}s`;
	const minutes = Math.floor(seconds / 60);
	if (minutes < 60) return `${minutes}m ${String(Math.round(seconds % 60)).padStart(2, '0')}s`;
	return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
}

export { formatCount } from '@/lib/intl';

/** "Dana Chen" → "Dana". */
export function firstName(name: string) {
	return name.trim().split(/\s+/)[0] ?? name;
}

/** Up to two initials: "Dana Chen" → "DC". Empty when the name has nothing to show; callers fall back to an icon or "?". */
export function initials(name: string) {
	return initialsOf(name) ?? '';
}

/** A readable name for an email nobody has a profile for yet: "jo.park@x.com" → "Jo Park". */
export function nameFromEmail(email: string) {
	const local = email.split('@')[0] ?? email;
	return local
		.split(/[._-]+/)
		.filter(Boolean)
		.map((part) => part[0]!.toUpperCase() + part.slice(1))
		.join(' ');
}

