													<span className="block h-full rounded-full bg-primary/70" style={{ width: `${Math.max(2, share * 100)}%` }} />
												</span>
												<span className="truncate text-xs text-muted-foreground tabular-nums">
													{row.people.length} {row.people.length === 1 ? 'person' : 'people'} · {Math.round(share * 100)}% of views
												</span>
											</span>
										</button>
									</td>
									<td className="text-end align-top whitespace-nowrap text-foreground tabular-nums">{row.views}</td>
									<td className="text-end align-top whitespace-nowrap text-muted-foreground tabular-nums">{formatDuration(row.seconds)}</td>
									<td className="text-end align-top whitespace-nowrap text-muted-foreground tabular-nums">{format.relative(row.last)}</td>
								</tr>
								{expanded
									? row.people.map((entry) => {
											const who = person(entry.personId);
											return (
												<tr key={entry.personId} className={cn(tableRowClass, 'bg-muted/30')}>
													<td className="w-full max-w-0">
														{/* Indented by the chevron and its gap, so people line up under their company's name. */}
														<button
															type="button"
															onClick={() => openTrace(entry.personId, room.id)}
															className={cn('-mx-1 ms-[calc(0.875rem+0.25rem)] flex max-w-full cursor-pointer items-center gap-2 rounded-md px-1 text-start hover:text-link', focusRingClass)}
														>
															<PersonAvatar person={who} size="xs" />
															<span title={who?.name ?? 'Someone'} className="truncate">{who?.name ?? 'Someone'}</span>
														</button>
													</td>
													<td className="text-end whitespace-nowrap tabular-nums">{entry.views}</td>
													<td className="text-end whitespace-nowrap text-muted-foreground tabular-nums">{formatDuration(entry.seconds)}</td>
													<td className="text-end whitespace-nowrap text-muted-foreground tabular-nums">{format.relative(entry.last)}</td>
												</tr>
											);
										})
									: null}
							</React.Fragment>
						);
					})}
					{rows.length === 0 ? (
						<tr className={tableRowClass}>
							<td colSpan={4} className="py-8 text-center text-muted-foreground">
								No reading yet.
							</td>
						</tr>
					) : null}
				</tbody>
			</TableSurface>
		</section>
	);
}

/**
 * Who reads what: views, downloads, active readers, and reading time over two
 * weeks, the documents drawing the most attention, engagement by company, and
 * guests who have gone quiet.
 */
export function InsightsTab({ room }: { room: Room }) {
	const { data, person, openTrace, format, document } = useDataRooms();
	const insights = useRoomInsights(room);
	const { thisWeek, lastWeek } = insights;

	const documents = [...insights.byDocument.entries()]
		.flatMap(([documentId, stats]) => {
			const found = document(documentId);
			return found ? [{ document: found, stats }] : [];
		})
		.sort((a, b) => b.stats.views - a.stats.views || b.stats.readers.size - a.stats.readers.size)
		.slice(0, 8);

	const companies = React.useMemo(() => {
		const groups = new Map<string, CompanyRow>();
		for (const [personId, row] of insights.byPerson) {
			const who = person(personId);
			const name = who?.guest ? (who.company ?? 'Guests') : data.org.name;
			const group = groups.get(name) ?? { name, people: [], views: 0, seconds: 0, last: row.last };
			group.people.push({ personId, ...row });
			group.views += row.views;
			group.seconds += row.seconds;
			if (row.last > group.last) group.last = row.last;
			groups.set(name, group);
		}
		for (const group of groups.values()) group.people.sort((a, b) => b.views - a.views);
		return [...groups.values()].sort((a, b) => b.views - a.views);
	}, [data.org.name, insights.byPerson, person]);

	const totalViews = companies.reduce((sum, row) => sum + row.views, 0);

	const quiet = roomPeople(data, room.id)
		.filter(({ person: who, access }) => who.guest && access.level !== 'none')
		.map(({ person: who }) => ({ person: who, last: insights.lastSeen.get(who.id) }))
		.filter((entry) => !entry.last || insights.now - Date.parse(entry.last) >= QUIET_DAYS * DAY_MS);

	const stats = [
		{ label: 'Views', icon: Eye, value: format.count(thisWeek.views + lastWeek.views), hint: trend(thisWeek.views, lastWeek.views) },
		{ label: 'Downloads', icon: Download, value: format.count(thisWeek.downloads + lastWeek.downloads), hint: trend(thisWeek.downloads, lastWeek.downloads) },
		{
			label: 'Active readers',
			icon: Users,
			value: format.count(new Set([...thisWeek.readers, ...lastWeek.readers]).size),
			hint: trend(thisWeek.readers.size, lastWeek.readers.size),
		},
		{ label: 'Reading time', icon: Clock, value: formatDuration(thisWeek.seconds + lastWeek.seconds), hint: trend(thisWeek.seconds, lastWeek.seconds) },
	];

	return (
		<div className="min-h-0 flex-1 overflow-y-auto">
			<div className="mx-auto flex w-full max-w-6xl flex-col gap-6 px-4 py-5 @3xl/view:px-6">
				<Panel title="Last 14 days" description="Compared with the week before." className={enterClass}>
					<div className="grid grid-cols-2 gap-x-6 gap-y-4 @3xl/view:grid-cols-4">
						{stats.map((stat) => (
							<StatTile key={stat.label} label={stat.label} icon={stat.icon} value={stat.value} hint={stat.hint} />
						))}
					</div>
				</Panel>

				<div className={enterClass} style={staggerStyle(1)}>
					<DailyChart days={insights.days} />
				</div>

				{quiet.length ? (
					<Panel
						title="Gone quiet"
						description={`Guests with access who haven’t opened anything in ${QUIET_DAYS} days.`}
						className={enterClass}
						style={staggerStyle(2)}
					>
						<ul className="flex flex-col">
							{quiet.map(({ person: who, last }, index) => (
								<li key={who.id} className={cn('flex items-center gap-3 py-2', index > 0 && 'border-t border-dashed border-foreground/10')}>
									<PersonAvatar person={who} size="sm" />
									<span className="min-w-0 flex-1 truncate text-[0.8125rem] text-foreground">
										{who.name}
										{who.company ? <span className="text-muted-foreground"> · {who.company}</span> : null}
									</span>
									<span className="flex shrink-0 items-center gap-1 text-xs text-muted-foreground tabular-nums">
										<Moon aria-hidden="true" className="size-3" />
										{last ? `Last seen ${format.relative(last)}` : 'Never opened anything'}
									</span>
									<button
										type="button"
										onClick={() => openTrace(who.id, room.id)}
										className={cn('shrink-0 rounded-sm text-xs text-muted-foreground underline-offset-4 hover:text-foreground hover:underline', focusRingClass)}
									>
										Access<span className="sr-only"> for {who.name}</span>
									</button>
								</li>
							))}
						</ul>
					</Panel>
				) : null}

				<div className={cn('grid grid-cols-1 gap-6 @min-[90rem]/view:grid-cols-2', enterClass)} style={staggerStyle(3)}>
					<MostRead rows={documents} />
					<Companies room={room} rows={companies} totalViews={totalViews} />
				</div>
			</div>
		</div>
	);
}

'use client';

import { Info, TriangleAlert, X } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogDescription, DialogFooter, DialogHeader, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import { type AccessEnd, AccessEndPicker, resolveAccessEnd } from '@/components/ui/data-rooms/access-end';
import { roomPeople } from '@/components/ui/data-rooms/access';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { isEmail } from '@/components/ui/data-rooms/format';
import { ChoiceSelect, PersonAvatar } from '@/components/ui/data-rooms/parts';
import type { Person, Room } from '@/components/ui/data-rooms/types';
import { useCommand } from '@/components/ui/data-rooms/use-command';

type InviteDialogProps = {
	roomId: string | null;
	open: boolean;
	onOpenChange: (open: boolean) => void;
};

type Token = { email: string; person?: Person };

/** Splits pasted or typed text into candidate emails. */
function splitEmails(text: string) {
	return text
		.split(/[\s,;]+/)
		.map((part) => part.trim())
		.filter(Boolean);
}

/**
 * Invite people to a room by email: org members join right away, everyone
 * else joins as a guest who only sees this room. Pick the role and,
 * optionally, when their access ends.
 */
export function InviteDialog({ roomId, open, onOpenChange }: InviteDialogProps) {
	const { room } = useDataRooms();
	const target = roomId ? room(roomId) : undefined;
	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			{target ? (
				<DialogPopup className="max-w-md">
					{/* Keyed by the room and remounted on open, so every visit starts empty. */}
					{open ? <InviteForm key={target.id} room={target} onDone={() => onOpenChange(false)} /> : null}
				</DialogPopup>
			) : null}
		</Dialog>
	);
}

function InviteForm({ room, onDone }: { room: Room; onDone: () => void }) {
	const { data, format } = useDataRooms();
	const command = useCommand();
	const defaultRole = data.roles.find((role) => role.isDefault) ?? data.roles[0];
	const [tokens, setTokens] = React.useState<Token[]>([]);
	const [draft, setDraft] = React.useState('');
	const [roleId, setRoleId] = React.useState(defaultRole?.id ?? '');
	const [ending, setEnding] = React.useState<AccessEnd>('never');
	const [message, setMessage] = React.useState('');
	/** Problems with what was typed, before anything is sent. */
	const [notice, setNotice] = React.useState<string | null>(null);
	const inputRef = React.useRef<HTMLInputElement>(null);
	const listId = React.useId();
	const roleHelpId = React.useId();

	const inRoom = React.useMemo(() => new Set(roomPeople(data, room.id).map((entry) => entry.person.id)), [data, room.id]);
	const role = data.roles.find((candidate) => candidate.id === roleId);
	const guests = tokens.filter((token) => !token.person || token.person.guest);
	const guestsBlocked = guests.length > 0 && !data.inheritance.allowGuests;

	const suggestions = React.useMemo(() => {
		const needle = draft.trim().toLowerCase();
		if (!needle) return [];
		return data.people
			.filter((person) => !inRoom.has(person.id) && !tokens.some((token) => token.person?.id === person.id))
			.filter((person) => person.name.toLowerCase().includes(needle) || person.email.toLowerCase().includes(needle))
			.slice(0, 5);
	}, [data.people, draft, inRoom, tokens]);

	const add = (values: string[]) => {
		const invalid = values.filter((value) => !isEmail(value));
		const fresh: Token[] = [];
		for (const value of values.filter(isEmail)) {
			const email = value.toLowerCase();
			if (tokens.some((token) => token.email === email) || fresh.some((token) => token.email === email)) continue;
			fresh.push({ email, person: data.people.find((person) => person.email.toLowerCase() === email) });
		}
		if (fresh.length) setTokens((current) => [...current, ...fresh.filter((token) => !current.some((candidate) => candidate.email === token.email))]);
		setNotice(invalid.length ? `${invalid.join(', ')} ${invalid.length === 1 ? 'isn’t' : 'aren’t'} a valid email.` : null);
		command.clearError();
	};

	const commitDraft = () => {
		if (!draft.trim()) return;
		add(splitEmails(draft));
		setDraft('');
	};

	const pick = (person: Person) => {
		setTokens((current) => [...current, { email: person.email.toLowerCase(), person }]);
		setDraft('');
		inputRef.current?.focus();
	};

	const expiresAt = resolveAccessEnd(ending, room, data.clock);

	const submit = async (event: React.FormEvent) => {
		event.preventDefault();
		const pending = draft.trim() ? splitEmails(draft).filter(isEmail) : [];
		const all = [...tokens, ...pending.filter((email) => !tokens.some((token) => token.email === email.toLowerCase())).map((email) => ({ email: email.toLowerCase(), person: data.people.find((person) => person.email.toLowerCase() === email.toLowerCase()) }))];
		if (!all.length) {
			setNotice('Add at least one email.');
			inputRef.current?.focus();
			return;
		}
		if (guestsBlocked) return;
		setNotice(null);
		const sent = await command.run({
			type: 'invite',
			roomId: room.id,
			invites: all.map((token) => ({ email: token.email, personId: token.person?.id })),
			roleId,
			expiresAt,
			message: message.trim() || undefined,
		});
		if (sent) onDone();
	};

	const error = notice ?? command.error;

	return (
		<form onSubmit={submit} noValidate className="flex min-h-0 flex-col">
			<DialogHeader variant="band" className="gap-1.5">
				<DialogTitle className="text-base font-medium">Invite to {room.name}</DialogTitle>
				<DialogDescription className="text-[0.8125rem]">People from {data.org.name} join right away. Everyone else joins as a guest.</DialogDescription>
			</DialogHeader>
			<div className="flex min-h-0 flex-col gap-4 overflow-y-auto px-6 pb-5">
				<div className="flex flex-col gap-1.5">
					<label htmlFor={`${listId}-input`} className="text-[0.8125rem] font-medium text-foreground">
						Emails
					</label>
					<div
						className={cn(
							'flex min-h-9 flex-wrap items-center gap-1 rounded-md border border-border bg-card px-1.5 py-1 shadow-2xs focus-within:ring-[3px] focus-within:ring-ring/50',
						)}
						onClick={() => inputRef.current?.focus()}
					>
						{tokens.map((token) => (
							<span
								key={token.email}
								className={cn(
									'inline-flex h-6 max-w-full items-center gap-1 rounded-[6px] border pe-0.5 ps-1 text-xs',
									token.person && !token.person.guest ? 'border-border bg-muted/60 text-foreground' : 'border-dashed border-foreground/30 text-foreground',
								)}
							>
								{token.person ? <PersonAvatar person={token.person} size="xs" className="size-4 text-[0.5rem]" /> : null}
								<span title={token.person?.name ?? token.email} className="truncate">{token.person?.name ?? token.email}</span>
								{!token.person || token.person.guest ? <span className="text-[0.625rem] text-muted-foreground">Guest</span> : null}
								<button
									type="button"
									aria-label={`Remove ${token.email}`}
									onClick={(event) => {
										event.stopPropagation();
										setTokens((current) => current.filter((candidate) => candidate.email !== token.email));
									}}
									className={cn('grid size-4 cursor-pointer place-items-center rounded-[4px] text-muted-foreground hover:bg-overlay-hover hover:text-foreground', focusRingClass)}
								>
									<X aria-hidden="true" className="size-3" />
								</button>
							</span>
						))}
						<input
							ref={inputRef}
							id={`${listId}-input`}
							type="text"
							inputMode="email"
							autoComplete="off"
							role="combobox"
							aria-expanded={suggestions.length > 0}
							aria-controls={listId}
							aria-autocomplete="list"
							value={draft}
							placeholder={tokens.length ? '' : 'name@company.com'}
							onChange={(event) => setDraft(event.target.value)}
							onKeyDown={(event) => {
								if (event.key === 'Enter' || event.key === ',' || event.key === ' ' || event.key === 'Tab') {
									if (!draft.trim()) return;
									const [only] = suggestions;
									if (event.key === 'Enter' && suggestions.length === 1 && only && !isEmail(draft)) {
										event.preventDefault();
										pick(only);
										return;
									}
									if (event.key !== 'Tab') event.preventDefault();
									commitDraft();
								} else if (event.key === 'Backspace' && !draft && tokens.length) {
									setTokens((current) => current.slice(0, -1));
								}
							}}
							onPaste={(event) => {
								const text = event.clipboardData.getData('text');
								if (!/[\s,;]/.test(text)) return;
								event.preventDefault();
								add(splitEmails(text));
							}}
							onBlur={commitDraft}
							className="h-6 min-w-32 flex-1 bg-transparent px-1 text-[0.8125rem] text-foreground outline-none placeholder:text-subtle-foreground pointer-coarse:text-base"
						/>
					</div>
					{suggestions.length ? (
						<ul id={listId} role="listbox" aria-label="People in the organization" className="flex flex-col rounded-md border border-border bg-card p-1 shadow-card">
							{suggestions.map((person) => (
								<li key={person.id} role="option" aria-selected={false}>
									<button
										type="button"
										onMouseDown={(event) => event.preventDefault()}
										onClick={() => pick(person)}
										className={cn('flex w-full cursor-pointer items-center gap-2 rounded-[5px] px-2 py-1.5 text-start hover:bg-overlay-hover', focusRingClass)}
									>
										<PersonAvatar person={person} size="sm" />
										<span className="min-w-0 flex-1">
											<span title={person.name} className="block truncate text-[0.8125rem] text-foreground">{person.name}</span>
											<span title={person.email} className="block truncate text-xs text-muted-foreground">{person.email}</span>
										</span>
										{person.guest ? <span className="text-xs text-muted-foreground">Guest</span> : null}
									</button>
								</li>
							))}
						</ul>
					) : null}
				</div>

				{guests.length ? (
					guestsBlocked ? (
						<p role="alert" className="flex items-start gap-2 rounded-md bg-destructive/10 px-3 py-2 text-[0.8125rem] text-destructive">
							<TriangleAlert aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
							{data.org.name} doesn’t allow guests from outside the organization. Remove {guests.length === 1 ? 'that email' : 'those emails'} or ask an
							organization admin.
						</p>
					) : (
						<p className="flex items-start gap-2 rounded-md bg-muted/60 px-3 py-2 text-[0.8125rem] text-muted-foreground">
							<Info aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
							<span>
								<span className="text-foreground tabular-nums">{guests.length}</span> {guests.length === 1 ? 'person' : 'people'} outside {data.org.name} will join as
								{guests.length === 1 ? ' a guest' : ' guests'}. They only see this room.
							</span>
						</p>
					)
				) : null}

				<div className="flex flex-col gap-1.5">
					<label htmlFor={`${listId}-role`} className="text-[0.8125rem] font-medium text-foreground">
						Role
					</label>
					<ChoiceSelect
						id={`${listId}-role`}
						describedBy={roleHelpId}
						className="w-full"
						value={roleId}
						onValueChange={setRoleId}
						options={data.roles.map((candidate) => ({ value: candidate.id, label: candidate.name }))}
					/>
					<p id={roleHelpId} className="text-xs text-muted-foreground">
						{role?.description ?? ''}
					</p>
				</div>

				<div className="flex flex-col gap-1.5">
					<span className="text-[0.8125rem] font-medium text-foreground">Access ends</span>
					<AccessEndPicker room={room} value={ending} onChange={setEnding} />
					{expiresAt ? <p className="text-xs text-muted-foreground tabular-nums">On {format.date(expiresAt)}</p> : null}
				</div>

				<div className="flex flex-col gap-1.5">
					<label htmlFor={`${listId}-message`} className="text-[0.8125rem] font-medium text-foreground">
						Message <span className="font-normal text-muted-foreground">(optional)</span>
					</label>
					<Textarea
						id={`${listId}-message`}
						size="sm"
						value={message}
						onChange={(event) => setMessage(event.target.value)}
						placeholder="Add a note to the invite"
						className="text-[0.8125rem]"
					/>
				</div>

				{error ? (
					<p role="alert" className="text-[0.8125rem] text-destructive">
						{error}
					</p>
				) : null}
			</div>
			<DialogFooter>
				<Button type="button" size="sm" variant="outline" onClick={onDone}>
					Cancel
				</Button>
				<Button type="submit" size="sm" disabled={command.pending || command.locked || guestsBlocked} aria-busy={command.pending || undefined}>
					{command.pending ? 'Sending…' : tokens.length > 1 ? `Invite ${tokens.length} people` : 'Send invite'}
				</Button>
			</DialogFooter>
		</form>
	);
}

'use client';

import { Info } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Dialog, DialogDescription, DialogFooter, DialogHeader, DialogPanel, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { dashedRule } from '@/components/ui/workspace-kit/surface';
import { leadsUnit, unitChain } from '@/components/ui/data-rooms/access';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { ChoiceSelect, FormField } from '@/components/ui/data-rooms/parts';
import type { DataRoomsData, Room, RoomPolicies } from '@/components/ui/data-rooms/types';
import { useCommand } from '@/components/ui/data-rooms/use-command';

type NewRoomDialogProps = { unitId?: string; open: boolean; onOpenChange: (open: boolean) => void };

const POLICY_ROWS: { key: keyof RoomPolicies; label: string; description: string }[] = [
	{ key: 'restricted', label: 'Restricted', description: 'Only people you add, plus owners and admins above it, can open the room.' },
	{ key: 'viewOnly', label: 'View only', description: 'Documents open in the viewer but can’t be downloaded.' },
	{ key: 'watermark', label: 'Watermark', description: 'Every page shows the reader’s name, email, and the time.' },
	{ key: 'requireAgreement', label: 'Require agreement', description: 'People accept your terms before they can enter.' },
];

const DEFAULT_AGREEMENT =
	'You are receiving confidential information for the sole purpose of evaluating this opportunity. Keep everything in this room confidential, share it only with advisors bound by the same terms, and do not copy or forward it.';

function list(names: string[]) {
	return names.length <= 1 ? (names[0] ?? '') : `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`;
}

/** Who joins a new room on their own, in plain words. */
function joinNote(data: DataRoomsData, unitId: string, restricted: boolean) {
	const chain = unitChain(data, unitId);
	const names = list(chain.map((unit) => unit.name));
	const nearest = chain[0]?.name ?? 'the unit';
	const { owners, admins, members } = data.inheritance;
	const lines: string[] = [];
	if (owners && admins) lines.push(`Owners and admins of ${names} join automatically.`);
	else if (owners) lines.push(`Owners of ${names} join automatically.`);
	else if (admins) lines.push(`Admins of ${names} join automatically.`);
	else lines.push('Nobody joins automatically; invite everyone who needs access.');
	if (!members) lines.push('Members don’t join on their own.');
	else if (restricted) lines.push(`Members of ${nearest} won’t, because the room is restricted.`);
	else lines.push(`Members of ${nearest} join with their usual role.`);
	lines.push('You’ll own the room.');
	return lines.join(' ');
}

function NewRoomForm({ unitId: initialUnit, onDone }: { unitId?: string; onDone: () => void }) {
	const { data, viewerId, openRoom } = useDataRooms();
	const command = useCommand();
	// Rooms can be created in any unit the person leads, held there or carried down from above.
	const units = React.useMemo(() => data.units.filter((unit) => leadsUnit(data, viewerId, unit.id)), [data, viewerId]);
	const [unitId, setUnitId] = React.useState(() => (initialUnit && units.some((unit) => unit.id === initialUnit) ? initialUnit : (units[0]?.id ?? '')));
	const [name, setName] = React.useState('');
	const [description, setDescription] = React.useState('');
	const [closesOn, setClosesOn] = React.useState('');
	const [policies, setPolicies] = React.useState<RoomPolicies>({ restricted: true, viewOnly: false, watermark: true, requireAgreement: false });
	const [agreementTitle, setAgreementTitle] = React.useState('Confidentiality agreement');
	const [agreementBody, setAgreementBody] = React.useState(DEFAULT_AGREEMENT);
	const [invalid, setInvalid] = React.useState<string | null>(null);
	const error = invalid ?? command.error;
	const busy = command.pending;
	const id = React.useId();

	const submit = async (event: React.FormEvent) => {
		event.preventDefault();
		if (!name.trim()) return setInvalid('Give the room a name.');
		if (!unitId) return setInvalid('Choose who owns the room.');
		setInvalid(null);
		const room: Room = {
			id: `local-room-${Date.now().toString(36)}`,
			unitId,
			name: name.trim(),
			description: description.trim() || undefined,
			status: 'active',
			createdAt: data.clock,
			createdBy: viewerId,
			closesAt: closesOn ? new Date(`${closesOn}T17:00:00.000Z`).toISOString() : undefined,
			policies,
			agreement: policies.requireAgreement ? { title: agreementTitle.trim() || 'Agreement', body: agreementBody.trim(), version: 1, updatedAt: data.clock } : undefined,
		};
		if (await command.run({ type: 'create-room', room })) {
			openRoom(room.id, 'documents');
			onDone();
		}
	};

	return (
		<form onSubmit={submit} noValidate className="flex min-h-0 flex-col">
			<DialogHeader variant="band" className="gap-1">
				<DialogTitle className="text-base font-medium">New room</DialogTitle>
				<DialogDescription className="text-[0.8125rem]">A private space for documents, people, and questions.</DialogDescription>
			</DialogHeader>
			<DialogPanel className="flex flex-col gap-4">
				<FormField label="Name" htmlFor={`${id}-name`}>
					<Input id={`${id}-name`} value={name} placeholder="Project Halcyon" autoFocus onChange={(event) => setName(event.target.value)} aria-invalid={invalid === 'Give the room a name.' || undefined} />
				</FormField>
				<div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
					<FormField label="Owned by" htmlFor={`${id}-unit`}>
						<ChoiceSelect
							id={`${id}-unit`}
							value={unitId}
							onValueChange={setUnitId}
							className="w-full"
							options={units.map((unit) => ({ value: unit.id, label: `${unit.name} · ${unit.kind}` }))}
						/>
					</FormField>
					<FormField label="Closes" htmlFor={`${id}-closes`} hint="Optional. Shown as a deadline.">
						<Input id={`${id}-closes`} type="date" value={closesOn} onChange={(event) => setClosesOn(event.target.value)} />
					</FormField>
				</div>
				<FormField label="Description" htmlFor={`${id}-description`}>
					<Textarea id={`${id}-description`} value={description} rows={2} placeholder="What the room is for" onChange={(event) => setDescription(event.target.value)} />
				</FormField>

				<fieldset className="flex flex-col">
					<legend className="mb-1 text-[0.8125rem] font-medium text-foreground">Protection</legend>
					{POLICY_ROWS.map((row, index) => {
						const switchId = `${id}-${row.key}`;
						return (
							<div key={row.key} className={cn('flex items-start gap-3 py-2', index > 0 && cn('border-t', dashedRule))}>
								<div className="min-w-0 flex-1">
									<label htmlFor={switchId} className="text-[0.8125rem] text-foreground">
										{row.label}
									</label>
									<p className="text-pretty text-xs text-muted-foreground">{row.description}</p>
								</div>
								<Switch
									id={switchId}
									className="-my-2.5 -me-1.5"
									checked={policies[row.key]}
									onCheckedChange={(checked) => setPolicies((current) => ({ ...current, [row.key]: checked }))}
								/>
							</div>
						);
					})}
				</fieldset>

				{policies.requireAgreement ? (
					<div className="flex flex-col gap-3 rounded-lg border border-border bg-muted/40 p-3">
						<FormField label="Agreement title" htmlFor={`${id}-agreement-title`}>
							<Input id={`${id}-agreement-title`} value={agreementTitle} onChange={(event) => setAgreementTitle(event.target.value)} />
						</FormField>
						<FormField label="Terms" htmlFor={`${id}-agreement-body`}>
							<Textarea id={`${id}-agreement-body`} value={agreementBody} rows={4} onChange={(event) => setAgreementBody(event.target.value)} />
						</FormField>
					</div>
				) : null}

				{unitId ? (
					<p aria-live="polite" className="flex gap-2 rounded-lg bg-muted/60 px-3 py-2.5 text-[0.8125rem] text-muted-foreground">
						<Info aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
						<span className="text-pretty">{joinNote(data, unitId, policies.restricted)}</span>
					</p>
				) : null}

				{error ? (
					<p role="alert" className="text-[0.8125rem] text-destructive">
						{error}
					</p>
				) : null}
			</DialogPanel>
			<DialogFooter>
				<Button type="button" size="sm" variant="outline" disabled={busy} onClick={onDone}>
					Cancel
				</Button>
				<Button type="submit" size="sm" disabled={busy || command.locked || units.length === 0} aria-busy={busy || undefined}>
					{busy ? 'Creating…' : 'Create room'}
				</Button>
			</DialogFooter>
		</form>
	);
}

