import { ChatContainer } from '@/components/ui/ai/chat-container';
import { PromptInput, PromptInputAction, PromptInputActions, PromptInputTextarea } from '@/components/ui/ai/prompt-input';
import { PromptSuggestion, PromptSuggestions } from '@/components/ui/ai/prompt-suggestion';
import { TextShimmer } from '@/components/ui/ai/text-shimmer';
import { Button } from '@/components/ui/button';
import { enterClass, focusRingClass, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { useReducedMotion } from '@/components/ui/workspace-kit/reduced-motion';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { DocumentGlyph } from '@/components/ui/data-rooms/parts';
import type { AssistantAnswer, Citation, DataRoomDocument, Room } from '@/components/ui/data-rooms/types';

/** Pacing, in milliseconds: long enough to read as searching, short enough to never feel slow. */
const TIMING = { search: 600, charMs: 9, minReveal: 280, maxReveal: 2600 } as const;

type Turn =
	| { id: string; role: 'user'; text: string; documentId?: string }
	| { id: string; role: 'assistant'; status: 'searching' | 'answering' | 'done'; answer?: AssistantAnswer }
	| { id: string; role: 'error'; text: string };

/** Reveals text over a duration tied to its length; instantly under reduced motion. */
function RevealText({ text, onDone }: { text: string; onDone: () => void }) {
	const reduced = useReducedMotion();
	const [shown, setShown] = React.useState(reduced ? text.length : 0);
	const onDoneRef = useLatest(onDone);

	React.useEffect(() => {
		if (reduced) {
			setShown(text.length);
			onDoneRef.current();
			return;
		}
		const duration = Math.min(TIMING.maxReveal, Math.max(TIMING.minReveal, text.length * TIMING.charMs));
		const started = performance.now();
		let frame = 0;
		const step = (time: number) => {
			const progress = Math.min(1, (time - started) / duration);
			setShown(Math.round(text.length * progress));
			if (progress < 1) frame = window.requestAnimationFrame(step);
			else onDoneRef.current();
		};
		frame = window.requestAnimationFrame(step);
		return () => window.cancelAnimationFrame(frame);
	}, [onDoneRef, reduced, text]);

	return (
		<>
			<span aria-hidden="true">{text.slice(0, shown)}</span>
			<span className="sr-only">{text}</span>
		</>
	);
}

