/**
 * "Ask this room": questions answered from the room's documents, citing only
 * what the reader can open. Answers come from the host when it runs an
 * assistant, otherwise from the scripted replies in the data.
 */
export function RoomAssistant({ room, onClose }: { room: Room; onClose: () => void }) {
	const { data, answerAssistant, assistantPrompt, document } = useDataRooms();
	const [turns, setTurns] = React.useState<Turn[]>([]);
	const [value, setValue] = React.useState('');
	const counter = React.useRef(0);
	const mounted = React.useRef(true);
	const handledKey = React.useRef(assistantPrompt?.key ?? 0);
	const busy = turns.some((turn) => turn.role === 'assistant' && turn.status !== 'done');

	React.useEffect(() => {
		mounted.current = true;
		return () => {
			mounted.current = false;
		};
	}, []);

	const ask = React.useCallback(
		async (prompt: string, documentId?: string) => {
			const text = prompt.trim();
			if (!text) return;
			const userId = `turn-${++counter.current}`;
			const replyId = `turn-${++counter.current}`;
			setTurns((current) => [...current, { id: userId, role: 'user', text, documentId }, { id: replyId, role: 'assistant', status: 'searching' }]);
			try {
				const [answer] = await Promise.all([answerAssistant(text, room.id, documentId), new Promise((resolve) => window.setTimeout(resolve, TIMING.search))]);
				if (!mounted.current) return;
				setTurns((current) => current.map((turn) => (turn.id === replyId ? { id: replyId, role: 'assistant', status: 'answering', answer } : turn)));
			} catch (reason) {
				if (!mounted.current) return;
				setTurns((current) =>
					current.map((turn) =>
						turn.id === replyId ? { id: replyId, role: 'error', text: reason instanceof Error ? reason.message : 'The assistant couldn’t answer that. Try again.' } : turn,
					),
				);
			}
		},
		[answerAssistant, room.id],
	);

	React.useEffect(() => {
		if (!assistantPrompt || assistantPrompt.key === handledKey.current) return;
		handledKey.current = assistantPrompt.key;
		void ask(assistantPrompt.prompt, assistantPrompt.documentId);
	}, [ask, assistantPrompt]);

	const submit = () => {
		if (!value.trim() || busy) return;
		void ask(value);
		setValue('');
	};

	const finish = (id: string) =>
		setTurns((current) => current.map((turn) => (turn.id === id && turn.role === 'assistant' ? { ...turn, status: 'done' } : turn)));

	return (
		<section aria-label={`Ask ${room.name}`} className="flex h-full min-w-0 flex-1 flex-col bg-background">
			<header className="flex h-12 shrink-0 items-center gap-2 border-b border-border px-3">
				<Sparkles aria-hidden="true" className="size-3.5 shrink-0 text-primary" />
				<div className="min-w-0 flex-1">
					<h2 className="truncate text-sm font-medium text-foreground">Ask {room.name}</h2>
				</div>
				<TooltipIconButton label="Close assistant" side="bottom" onClick={onClose}>
					<X aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
			</header>
			<p className="shrink-0 border-b border-dashed border-foreground/10 bg-muted/40 px-3 py-1.5 text-xs text-muted-foreground">Answers only use documents you can open.</p>

			<ChatContainer className="px-3">
				<div className="flex flex-col gap-4 py-4" aria-live="polite">
					{turns.length === 0 ? (
						<div className={cn('flex flex-col gap-4 pt-6', enterClass)}>
							<div className="flex flex-col items-center gap-2 text-center">
								<span className="grid size-9 place-items-center rounded-[10px] bg-card text-primary shadow-card">
									<Sparkles aria-hidden="true" className="size-4" />
								</span>
								<p className="text-sm font-medium text-foreground">What do you want to know?</p>
								<p className="max-w-64 text-[0.8125rem] text-pretty text-muted-foreground">Answers cite the documents they come from, so you can check them.</p>
							</div>
							{data.assistant?.suggestions.length ? (
								<PromptSuggestions label="Try asking">
									{data.assistant.suggestions.map((suggestion) => (
										<PromptSuggestion key={suggestion} onClick={() => void ask(suggestion)}>
											{suggestion}
										</PromptSuggestion>
									))}
								</PromptSuggestions>
							) : null}
						</div>
					) : null}
					{turns.map((turn) => {
						if (turn.role === 'user') {
							const doc = turn.documentId ? document(turn.documentId) : undefined;
							return (
								<div key={turn.id} className={cn('flex max-w-[88%] flex-col items-end gap-1 self-end', enterClass)}>
									<p className="rounded-2xl rounded-ee-md bg-primary px-3 py-2 text-sm leading-5 text-pretty text-primary-foreground">{turn.text}</p>
									{doc ? <span className="px-1 text-[0.6875rem] text-subtle-foreground">About {doc.name}</span> : null}
								</div>
							);
						}
						if (turn.role === 'error') {
							return (
								<p key={turn.id} role="alert" className={cn('rounded-xl border border-destructive/30 bg-destructive/5 px-3 py-2 text-[0.8125rem] text-destructive', enterClass)}>
									{turn.text}
								</p>
							);
						}
						return (
							<div key={turn.id} className={cn('flex flex-col', enterClass)}>
								<span className="mb-1 flex items-center gap-1 text-[0.6875rem] text-muted-foreground">
									<Sparkles aria-hidden="true" className="size-3" />
									Assistant
								</span>
								{turn.status === 'searching' || !turn.answer ? (
									<TextShimmer className="text-[0.8125rem] font-normal">Searching documents you can open…</TextShimmer>
								) : (
									<>
										<p className="text-sm leading-6 text-pretty text-foreground">
											{turn.status === 'answering' ? <RevealText text={turn.answer.text} onDone={() => finish(turn.id)} /> : turn.answer.text}
										</p>
										{turn.status === 'done' ? <Citations answer={turn.answer} /> : null}
									</>
								)}
							</div>
						);
					})}
				</div>
			</ChatContainer>

			<div className="shrink-0 px-3 pt-1 pb-3">
				<PromptInput value={value} onValueChange={setValue} onSubmit={submit} className="rounded-xl border-border bg-card p-1.5 shadow-sm">
					<PromptInputTextarea aria-label={`Ask a question about ${room.name}`} placeholder="Ask about this room…" className="min-h-9 px-1.5 py-1" />
					<PromptInputActions className="justify-end px-0">
						<PromptInputAction tooltip="Ask">
							<Button size="icon-xs" variant={value.trim() && !busy ? 'default' : 'secondary'} aria-label="Ask" disabled={!value.trim() || busy} className="size-7" onClick={submit}>
								<ArrowUp className="size-3.5" />
							</Button>
						</PromptInputAction>
					</PromptInputActions>
				</PromptInput>
			</div>
		</section>
	);
}

'use client';

import { useDirection } from '@base-ui/react/direction-provider';
import { Eye, Sparkles } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { focusRingClass, NavMenuButton, pressClass, scrollRowClass, ToneBadge, TooltipIconButton, useInert } from '@/components/ui/workspace-kit/primitives';
import { useScrollFade } from '@/lib/use-scroll-fade';
import { startViewTransition, ViewAnimation } from '@/components/ui/workspace-kit/view-transition';
import { needsAgreement } from '@/components/ui/data-rooms/access';
import { AgreementGate } from '@/components/ui/data-rooms/agreement-gate';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { daysUntil } from '@/components/ui/data-rooms/format';
import { DocumentsTab } from '@/components/ui/data-rooms/documents-tab';
import { InsightsTab } from '@/components/ui/data-rooms/insights-tab';
import { PeopleTab } from '@/components/ui/data-rooms/people-tab';
import { PreviewAsMenu } from '@/components/ui/data-rooms/preview-as-menu';
import { QuestionsTab } from '@/components/ui/data-rooms/questions-tab';
import { RoomAssistant } from '@/components/ui/data-rooms/room-assistant';
import { SettingsTab } from '@/components/ui/data-rooms/settings-tab';
import type { Room, RoomTab } from '@/components/ui/data-rooms/types';

const TABS: { value: RoomTab; label: string }[] = [
	{ value: 'documents', label: 'Documents' },
	{ value: 'people', label: 'People' },
	{ value: 'questions', label: 'Q&A' },
	{ value: 'insights', label: 'Insights' },
	{ value: 'settings', label: 'Settings' },
];

/** Deadlines closer than this get a warning dot beside the room name. */
const DEADLINE_SOON_DAYS = 7;

/** The tabs the acting person can open in a room. */
function useRoomTabs(room: Room) {
	const { can } = useDataRooms();
	const target = { kind: 'room', roomId: room.id } as const;
	const manages = can('manage_room', target);
	const people = can('invite', target) || can('manage_members', target);
	return TABS.filter((tab) => {
		if (tab.value === 'people') return people;
		if (tab.value === 'insights' || tab.value === 'settings') return manages;
		return true;
	});
}

/** A quiet dot beside the room name while its deadline is near; the date lives in the tooltip. */
function DeadlineDot({ room }: { room: Room }) {
	const { data, format } = useDataRooms();
	if (!room.closesAt) return null;
	const days = daysUntil(room.closesAt, data.clock);
	if (days < 0 || days > DEADLINE_SOON_DAYS) return null;
	const label = `Closes ${format.deadline(room.closesAt)}`;
	return (
		<Tooltip>
			<TooltipTrigger
				render={
					<span tabIndex={0} className={cn('grid size-4 shrink-0 cursor-default place-items-center rounded-full', focusRingClass)}>
						<span aria-hidden="true" className="size-1.5 rounded-full bg-warning" />
						<span className="sr-only">{label}</span>
					</span>
				}
			/>
			<TooltipContent side="bottom">{label}</TooltipContent>
		</Tooltip>
	);
}

/**
 * One room. A single header row carries the room name, its sections, and two
 * quiet tools (preview as someone, ask the assistant); each section owns its
 * own primary action. People who still have to accept the room's agreement
 * see it in place of the sections.
 */
function RoomView({ room }: { room: Room }) {
	const { data, tab, setTab, actingId, previewAs, person, setPreviewAs, can, assistantOpen, setAssistantOpen } = useDataRooms();
	const tabs = useRoomTabs(room);
	const active = tabs.some((candidate) => candidate.value === tab) ? tab : 'documents';
	const gated = needsAgreement(data, actingId, room.id);
	const canAsk = can('ask_assistant', { kind: 'room', roomId: room.id }) && Boolean(data.assistant) && !gated;
	const panelOpen = assistantOpen && canAsk;
	const panelRef = useInert<HTMLDivElement>(!panelOpen);
	const previewing = previewAs ? person(previewAs) : undefined;
	const openQuestions = data.questions.filter((question) => question.roomId === room.id && question.status === 'open').length;
	const tabId = React.useId();
	const rtl = useDirection() === 'rtl';
	const tabFade = useScrollFade<HTMLDivElement>();
	const [forward, backward] = rtl ? ['ArrowLeft', 'ArrowRight'] : ['ArrowRight', 'ArrowLeft'];

	const choose = (next: RoomTab) => startViewTransition(() => setTab(next));

	return (
		<div className="flex min-w-0 flex-1 flex-col">
			{/* Narrow: the sections wrap to their own full-width row under the name, so a long room name cannot squeeze them out. From 52rem: one row, the name capped at 40% (the five sections need about 22rem). */}
			<header className="flex min-h-12 shrink-0 flex-wrap items-center gap-x-3 gap-y-0.5 border-b border-border px-3 py-1.5">
				<NavMenuButton />
				<div className="flex min-w-0 flex-1 items-center gap-1.5 @min-[52rem]/view:max-w-[40%] @min-[52rem]/view:flex-none">
					<h1 title={room.name} className="truncate text-sm font-medium text-foreground">
						<bdi>{room.name}</bdi>
					</h1>
					<DeadlineDot room={room} />
					{room.status === 'archived' ? <ToneBadge tone="neutral">Archived</ToneBadge> : null}
				</div>
				{gated ? (
					<div className="hidden flex-1 @min-[52rem]/view:block" />
				) : (
					<div ref={tabFade.ref} style={tabFade.style} className={cn(scrollRowClass, 'order-last w-full min-w-0 @min-[52rem]/view:order-none @min-[52rem]/view:w-auto @min-[52rem]/view:flex-1')}>
						<div role="tablist" aria-label={`${room.name} sections`} className="flex w-max gap-0.5">
							{tabs.map((option) => {
								const selected = option.value === active;
								const count = option.value === 'questions' ? openQuestions : 0;
								return (
									<button
										key={option.value}
										type="button"
										role="tab"
										id={`${tabId}-${option.value}`}
										aria-selected={selected}
										aria-controls={`${tabId}-panel`}
										tabIndex={selected ? 0 : -1}
										onClick={() => choose(option.value)}
										onKeyDown={(event) => {
											if (event.key !== forward && event.key !== backward) return;
											event.preventDefault();
											const index = tabs.findIndex((candidate) => candidate.value === active);
											const next = tabs[(index + (event.key === forward ? 1 : tabs.length - 1)) % tabs.length]!;
											choose(next.value);
											event.currentTarget.parentElement?.querySelector<HTMLButtonElement>(`#${CSS.escape(`${tabId}-${next.value}`)}`)?.focus();
										}}
										className={cn(
											'inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-md px-2 text-[0.8125rem] pointer-coarse:h-9',
											pressClass,
											focusRingClass,
											selected ? 'bg-overlay-hover font-medium text-foreground' : 'text-muted-foreground hover:text-foreground',
										)}
									>
										{option.label}
										{count ? (
											<span className="text-xs text-warning tabular-nums">
												{count}
												<span className="sr-only"> open</span>
											</span>
										) : null}
									</button>
								);
							})}
						</div>
					</div>
				)}
				<div className="flex shrink-0 items-center gap-0.5">
					<PreviewAsMenu room={room} />
					{canAsk ? (
						<TooltipIconButton
							label={panelOpen ? 'Close the assistant' : `Ask about ${room.name}`}
							side="bottom"
							aria-pressed={panelOpen}
							className={cn(panelOpen && 'bg-overlay-hover text-foreground')}
							onClick={() => startViewTransition(() => setAssistantOpen(!panelOpen))}
						>
							<Sparkles aria-hidden="true" className="size-3.5" />
						</TooltipIconButton>
					) : null}
				</div>
			</header>

			{previewing ? (
				<div className="flex shrink-0 items-center gap-2 border-b border-border bg-[color-mix(in_oklab,var(--primary)_7%,var(--background))] px-4 py-2 text-[0.8125rem]">
					<Eye aria-hidden="true" className="size-3.5 shrink-0 text-primary" />
					<p className="min-w-0 flex-1 truncate text-foreground">
						Previewing as{' '}
						<span className="font-medium">
							<bdi>{previewing.name}</bdi>
						</span>
						{previewing.company ? <span className="text-muted-foreground"> · {previewing.company}</span> : null}
						<span className="hidden text-muted-foreground @xl/view:inline">. This is exactly what they can see and do.</span>
					</p>
					<Button size="xs" variant="ghost" onClick={() => setPreviewAs(null)}>
						Exit preview
					</Button>
				</div>
			) : null}

			<div className="flex min-h-0 flex-1">
				<div className={cn('flex min-w-0 flex-1 flex-col', panelOpen && 'hidden @4xl/view:flex')}>
					{gated ? (
						<div className="min-h-0 flex-1 overflow-y-auto">
							<AgreementGate room={room} />
						</div>
					) : (
						<ViewAnimation>
							<div key={active} id={`${tabId}-panel`} role="tabpanel" aria-labelledby={`${tabId}-${active}`} className="flex min-h-0 flex-1 flex-col">
								{active === 'documents' ? <DocumentsTab room={room} /> : null}
								{active === 'people' ? <PeopleTab room={room} /> : null}
								{active === 'questions' ? <QuestionsTab room={room} /> : null}
								{active === 'insights' ? <InsightsTab room={room} /> : null}
								{active === 'settings' ? <SettingsTab room={room} /> : null}
							</div>
						</ViewAnimation>
					)}
				</div>
				<div
					ref={panelRef}
					className={cn(
						'flex shrink-0 overflow-hidden border-border transition-[width,opacity] duration-(--duration-slow) ease-(--ease-out) motion-reduce:transition-none',
						panelOpen ? 'w-full opacity-100 @4xl/view:w-[380px] @4xl/view:border-s' : 'w-0 opacity-0',
					)}
				>
					{canAsk ? <RoomAssistant room={room} onClose={() => startViewTransition(() => setAssistantOpen(false))} /> : null}
				</div>
			</div>
		</div>
	);
}

export { RoomView };

'use client';

import { ChevronRight } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { enterClass, focusRingClass, staggerStyle } from '@/components/ui/workspace-kit/primitives';
import { dashedRule, Panel } from '@/components/ui/workspace-kit/surface';
import { ALL_PERMISSIONS, PERMISSION_COPY, roomPeople, unitChain } from '@/components/ui/data-rooms/access';
import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import { ChoiceSelect, FormField } from '@/components/ui/data-rooms/parts';
import type { Permission, Role, Room, RoomPolicies, RoomStatus } from '@/components/ui/data-rooms/types';
import { useCommand } from '@/components/ui/data-rooms/use-command';

function ErrorLine({ error }: { error: string | null }) {
	return error ? (
		<p role="alert" className="text-[0.8125rem] text-destructive">
			{error}
		</p>
	) : null;
}

const STATUS_OPTIONS: { value: RoomStatus; label: string }[] = [
	{ value: 'active', label: 'Active' },
	{ value: 'closing', label: 'Closing' },
	{ value: 'archived', label: 'Archived' },
];

function RoomDetails({ room }: { room: Room }) {
	const { run, pending: busy, error, locked } = useCommand();
	const initial = React.useMemo(
		() => ({ name: room.name, description: room.description ?? '', status: room.status, closesOn: room.closesAt?.slice(0, 10) ?? '' }),
		[room],
	);
	const [form, setForm] = React.useState(initial);
	const [source, setSource] = React.useState(initial);
	if (source !== initial) {
		setSource(initial);
		setForm(initial);
	}
	const id = React.useId();
	const dirty = form.name !== initial.name || form.description !== initial.description || form.status !== initial.status || form.closesOn !== initial.closesOn;

	const save = async (event: React.FormEvent) => {
		event.preventDefault();
		if (!dirty || !form.name.trim()) return;
		const time = room.closesAt?.slice(10) ?? 'T17:00:00.000Z';
		await run({
			type: 'update-room',
			roomId: room.id,
			patch: {
				name: form.name.trim(),
				description: form.description.trim() || undefined,
				status: form.status,
				closesAt: form.closesOn ? `${form.closesOn}${time}` : undefined,
			},
		});
	};

	return (
		<Panel title="Room" description="What people see in the sidebar and at the top of the room." className={enterClass}>
			<form onSubmit={save} className="flex flex-col gap-4">
				<FormField label="Name" htmlFor={`${id}-name`}>
					<Input id={`${id}-name`} value={form.name} disabled={locked} onChange={(event) => setForm({ ...form, name: event.target.value })} size="sm" />
				</FormField>
				<FormField label="Description" htmlFor={`${id}-description`}>
					<Textarea id={`${id}-description`} value={form.description} disabled={locked} rows={2} onChange={(event) => setForm({ ...form, description: event.target.value })} size="sm" />
				</FormField>
				<div className="grid grid-cols-1 gap-4 @md/view:grid-cols-2">
					<FormField label="Status" htmlFor={`${id}-status`} hint="Closing rooms show a badge; archived rooms leave the sidebar.">
						<ChoiceSelect
							id={`${id}-status`}
							value={form.status}
							disabled={locked}
							onValueChange={(next) => setForm({ ...form, status: STATUS_OPTIONS.find((option) => option.value === next)?.value ?? form.status })}
							className="w-full"
							options={STATUS_OPTIONS}
						/>
					</FormField>
					<FormField label="Closes on" htmlFor={`${id}-closes`} hint="Shown as a countdown in the room header.">
						<Input id={`${id}-closes`} type="date" value={form.closesOn} disabled={locked} onChange={(event) => setForm({ ...form, closesOn: event.target.value })} size="sm" />
					</FormField>
				</div>
				<ErrorLine error={error} />
				<div className="flex justify-end gap-2">
					<Button type="button" size="xs" variant="ghost" disabled={!dirty || busy} onClick={() => setForm(initial)}>
						Reset
					</Button>
					<Button type="submit" size="xs" disabled={!dirty || busy || locked || !form.name.trim()} aria-busy={busy || undefined}>
						{busy ? 'Saving…' : 'Save'}
					</Button>
				</div>
			</form>
		</Panel>
	);
}

const PROTECTIONS: { key: keyof RoomPolicies; label: string; description: string }[] = [
	{ key: 'restricted', label: 'Restricted', description: 'Only people added to the room can open it. Owners and admins above it still can.' },
	{ key: 'viewOnly', label: 'View only', description: 'Documents open in the viewer but can’t be downloaded, except by room managers.' },
	{ key: 'watermark', label: 'Watermark', description: 'Every page shows the reader’s name, email, and the time.' },
	{ key: 'requireAgreement', label: 'Require agreement', description: 'People accept the room’s agreement before they can enter.' },
];

function Protection({ room }: { room: Room }) {
	const { data } = useDataRooms();
	const { run, pending: busy, error, locked } = useCommand();
	const [pending, setPending] = React.useState<keyof RoomPolicies | null>(null);
	const chain = unitChain(data, room.unitId).reverse();
	const names = chain.map((unit) => unit.name);
	const list = (items: string[]) => (items.length <= 1 ? (items[0] ?? '') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`);
	const leaders = [data.inheritance.owners ? 'Owners' : null, data.inheritance.admins ? 'admins' : null].filter(Boolean) as string[];
	const lines: string[] = [];
	if (leaders.length) lines.push(`${leaders.join(' and ').replace(/^./, (char) => char.toUpperCase())} of ${list(names)} join this room automatically.`);
	if (data.inheritance.members && !room.policies.restricted) lines.push(`Members of ${list(names)} join too.`);
	else if (data.inheritance.members) lines.push('Members above it don’t join while the room is restricted.');
	if (!lines.length) lines.push('Nobody joins automatically; only people added to the room can open it.');

	const toggle = async (key: keyof RoomPolicies, value: boolean) => {
		setPending(key);
		await run({ type: 'update-room', roomId: room.id, patch: { policies: { ...room.policies, [key]: value } } });
		setPending(null);
	};

	return (
		<Panel title="Protection" description="How the room is opened, read, and shared." className={enterClass} style={staggerStyle(1)} footer={lines.join(' ')}>
			<ul className="flex flex-col">
				{PROTECTIONS.map((protection, index) => {
					const id = `protection-${room.id}-${protection.key}`;
					return (
						<li key={protection.key} className={cn('flex items-center gap-4 py-2', index > 0 && cn('border-t', dashedRule))}>
							<div className="min-w-0 flex-1">
								<label htmlFor={id} className="text-[0.8125rem] font-medium text-foreground">
									{protection.label}
								</label>
								<p id={`${id}-description`} className="text-[0.8125rem] text-pretty text-muted-foreground">
									{protection.description}
								</p>
							</div>
							<Switch
								id={id}
								aria-describedby={`${id}-description`}
								checked={room.policies[protection.key]}
								disabled={locked || (busy && pending === protection.key)}
								onCheckedChange={(checked) => toggle(protection.key, checked)}
							/>
						</li>
					);
				})}
			</ul>
			<ErrorLine error={error} />
		</Panel>
	);
}

function Agreement({ room }: { room: Room }) {
	const { data, can } = useDataRooms();
	const { run, pending: busy, error, locked } = useCommand();
	const current = room.agreement;
	const initial = React.useMemo(() => ({ title: current?.title ?? 'Confidentiality agreement', body: current?.body ?? '' }), [current]);
	const [form, setForm] = React.useState(initial);
	const [source, setSource] = React.useState(initial);
	if (source !== initial) {
		setSource(initial);
		setForm(initial);
	}
	const id = React.useId();
	const version = current?.version ?? 0;
	const dirty = form.title !== initial.title || form.body !== initial.body;

	const readers = roomPeople(data, room.id).filter(
		({ person, access }) => access.level !== 'none' && !can('manage_room', { kind: 'room', roomId: room.id }, person.id),
	);
	const accepted = readers.filter(({ person }) =>
		data.acceptances.some((acceptance) => acceptance.roomId === room.id && acceptance.personId === person.id && acceptance.version >= version),
	).length;

	const save = (nextVersion: number) =>
		run({
			type: 'update-room',
			roomId: room.id,
			patch: { agreement: { title: form.title.trim() || 'Agreement', body: form.body, version: nextVersion, updatedAt: data.clock } },
		});

	return (
		<Panel
			title="Agreement"
			description={
				version ? (
					<span className="tabular-nums">
						Version {version} · {accepted} of {readers.length} {readers.length === 1 ? 'person has' : 'people have'} accepted it
					</span>
				) : (
					'Write the terms people accept before entering.'
				)
			}
			className={enterClass}
			style={staggerStyle(2)}
		>
			<div className="flex flex-col gap-4">
				<FormField label="Title" htmlFor={`${id}-title`}>
					<Input id={`${id}-title`} value={form.title} disabled={locked} onChange={(event) => setForm({ ...form, title: event.target.value })} size="sm" />
				</FormField>
				<FormField label="Terms" htmlFor={`${id}-body`} hint="Blank lines start new paragraphs.">
					<Textarea id={`${id}-body`} value={form.body} disabled={locked} rows={8} onChange={(event) => setForm({ ...form, body: event.target.value })} size="sm" />
				</FormField>
				<ErrorLine error={error} />
				<div className="flex flex-wrap justify-end gap-2">
					{version ? (
						<Button size="xs" variant="outline" disabled={!dirty || busy || locked} onClick={() => save(version)}>
							Save
						</Button>
					) : null}
					<Button size="xs" disabled={(!dirty && version > 0) || busy || locked || !form.body.trim()} aria-busy={busy || undefined} onClick={() => save(version + 1)}>
						{version ? 'Save and ask everyone again' : 'Save agreement'}
					</Button>
				</div>
			</div>
		</Panel>
	);
}

function RoleEditor({ role }: { role: Role }) {
	const { run, pending: busy, error, locked } = useCommand();
	const [expanded, setExpanded] = React.useState(false);
	const [advanced, setAdvanced] = React.useState(false);
	const [draft, setDraft] = React.useState(role);
	const [source, setSource] = React.useState(role);
	if (source !== role) {
		setSource(role);
		setDraft(role);
	}
	const id = React.useId();
	const dirty =
		draft.name !== role.name ||
		(draft.description ?? '') !== (role.description ?? '') ||
		draft.permissions.length !== role.permissions.length ||
		draft.permissions.some((permission) => !role.permissions.includes(permission));

	const toggle = (permission: Permission, on: boolean) =>
		setDraft((current) => ({
			...current,
			permissions: on ? ALL_PERMISSIONS.filter((candidate) => candidate === permission || current.permissions.includes(candidate)) : current.permissions.filter((candidate) => candidate !== permission),
		}));

	return (
		<li className="py-1">
			<button
				type="button"
				aria-expanded={expanded}
				aria-controls={`${id}-panel`}
				onClick={() => setExpanded((value) => !value)}
				className={cn('-mx-1.5 flex w-[calc(100%+0.75rem)] cursor-pointer items-center gap-2 rounded-md px-1.5 py-1.5 text-start hover:bg-overlay-hover', focusRingClass)}
			>
				<ChevronRight
					aria-hidden="true"
					className={cn('size-3.5 shrink-0 text-muted-foreground transition-transform duration-(--duration-fast) motion-reduce:transition-none', expanded ? 'rotate-90' : 'rtl:-scale-x-100')}
				/>
				<span className="min-w-0 flex-1">
					<span className="text-[0.8125rem] font-medium text-foreground">{role.name}</span>
					{role.isDefault ? <span className="ms-1.5 text-xs text-muted-foreground">Default</span> : null}
					{role.description ? <span title={role.description} className="block truncate text-[0.8125rem] text-muted-foreground">{role.description}</span> : null}
				</span>
				<span className="shrink-0 text-xs text-muted-foreground tabular-nums">
					{role.permissions.length} of {ALL_PERMISSIONS.length}
				</span>
			</button>
			{expanded ? (
				<div id={`${id}-panel`} className="flex flex-col gap-3 pt-2 pb-3 ps-6">
					<div className="grid grid-cols-1 gap-3 @md/view:grid-cols-2">
						<FormField label="Name" htmlFor={`${id}-name`}>
							<Input id={`${id}-name`} value={draft.name} disabled={locked} onChange={(event) => setDraft({ ...draft, name: event.target.value })} size="sm" />
						</FormField>
						<FormField label="Description" htmlFor={`${id}-description`}>
							<Input id={`${id}-description`} value={draft.description ?? ''} disabled={locked} onChange={(event) => setDraft({ ...draft, description: event.target.value })} size="sm" />
						</FormField>
					</div>
					<button
						type="button"
						aria-expanded={advanced}
						onClick={() => setAdvanced((value) => !value)}
						className={cn('flex w-fit cursor-pointer items-center gap-1 rounded-sm text-xs text-muted-foreground hover:text-foreground', focusRingClass)}
					>
						<ChevronRight aria-hidden="true" className={cn('size-3 transition-transform duration-(--duration-fast) motion-reduce:transition-none', advanced ? 'rotate-90' : 'rtl:-scale-x-100')} />
						Advanced: permissions
					</button>
					{advanced ? (
						<fieldset className="grid grid-cols-1 gap-x-4 gap-y-2.5 rounded-lg border border-border bg-muted/30 p-3 @md/view:grid-cols-2">
							<legend className="sr-only">Permissions for {role.name}</legend>
							{ALL_PERMISSIONS.map((permission) => {
								const checkboxId = `${id}-${permission}`;
								return (
									<label key={permission} htmlFor={checkboxId} className="flex cursor-pointer items-start gap-2.5">
										<Checkbox
											id={checkboxId}
											checked={draft.permissions.includes(permission)}
											disabled={locked}
											onCheckedChange={(checked) => toggle(permission, checked === true)}
											className="mt-0.5"
										/>
										<span className="min-w-0">
											<span className="block text-[0.8125rem] text-foreground">{PERMISSION_COPY[permission].label}</span>
											<span className="block text-xs text-muted-foreground">{PERMISSION_COPY[permission].description}</span>
										</span>
									</label>
								);
							})}
						</fieldset>
					) : null}
					<ErrorLine error={error} />
					<div className="flex justify-end gap-2">
						<Button size="xs" variant="ghost" disabled={!dirty || busy} onClick={() => setDraft(role)}>
							Reset
						</Button>
						<Button
							size="xs"
							disabled={!dirty || busy || locked || !draft.name.trim()}
							aria-busy={busy || undefined}
							onClick={() => run({ type: 'save-role', role: { ...draft, name: draft.name.trim() } })}
						>
							Save role
						</Button>
					</div>
				</div>
			) : null}
		</li>
	);
}

function Roles() {
