/** The room search appears once the list is long enough to need it; ⌘K shows it any time. */
const SEARCH_AFTER_ROOMS = 8;

type DataRoomsSidebarProps = {
	collapsed?: boolean;
	onCollapsedChange?: (collapsed: boolean) => void;
	drawer?: boolean;
	onNavigate?: () => void;
};

/** Units in tree order (organization first, then each unit's children), each with the rooms the person can enter. */
function useRoomGroups(query: string) {
	const { data, actingId } = useDataRooms();
	return React.useMemo(() => {
		const needle = query.trim().toLowerCase();
		const rooms = data.rooms.filter(
			(room) => room.status !== 'archived' && canEnterRoom(data, actingId, room.id) && (!needle || room.name.toLowerCase().includes(needle)),
		);
		const depth = (unitId: string) => unitChain(data, unitId).length - 1;
		const ordered: { unitId: string; depth: number }[] = [];
		const visit = (parentId: string | null) => {
			for (const unit of data.units.filter((candidate) => candidate.parentId === parentId)) {
				ordered.push({ unitId: unit.id, depth: depth(unit.id) });
				visit(unit.id);
			}
		};
		visit(null);
		return ordered
			.map((entry) => ({ ...entry, rooms: rooms.filter((room) => room.unitId === entry.unitId) }))
			.filter((entry) => entry.rooms.length > 0);
	}, [actingId, data, query]);
}

/**
 * Workspace navigation: the organization menu, Home, the access map and
 * activity for people who manage rooms, and every room the person can enter,
 * grouped under the unit that owns it.
 */
function DataRoomsSidebar({ collapsed: collapsedProp = false, onCollapsedChange, drawer = false, onNavigate }: DataRoomsSidebarProps) {
	const { data, view, setView, roomId, openRoom, isManager, unit, can, previewAs, setPreviewAs, person, openNewRoom } = useDataRooms();
	const { locked } = useCommand();
	const collapsed = !drawer && collapsedProp;
	const [query, setQuery] = React.useState('');
	const [searchRevealed, setSearchRevealed] = React.useState(false);
	const [foldedUnits, setFoldedUnits] = React.useState<ReadonlySet<string>>(() => new Set());
	const groups = useRoomGroups(query);
	const roomCount = useRoomGroups('').reduce((sum, group) => sum + group.rooms.length, 0);
	const showSearch = roomCount > SEARCH_AFTER_ROOMS || searchRevealed || query !== '';
	const headingId = React.useId();
	const navRef = React.useRef<HTMLElement>(null);
	const searchRef = React.useRef<HTMLInputElement>(null);

	const toggleUnit = (unitId: string) =>
		setFoldedUnits((current) => {
			const next = new Set(current);
			if (next.has(unitId)) next.delete(unitId);
			else next.add(unitId);
			return next;
		});

	React.useEffect(() => {
		const onKeyDown = (event: KeyboardEvent) => {
			// Only the instance on screen answers, so a hidden rail and an open drawer never both react.
			if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== 'k' || !navRef.current?.offsetParent) return;
			event.preventDefault();
			onCollapsedChange?.(false);
			setSearchRevealed(true);
			window.requestAnimationFrame(() => searchRef.current?.focus());
		};
		document.addEventListener('keydown', onKeyDown);
		return () => document.removeEventListener('keydown', onKeyDown);
	}, [onCollapsedChange]);

	const select = (action: () => void) => () => {
		action();
		onNavigate?.();
	};

	const openQuestions = (room: Room) => data.questions.filter((question) => question.roomId === room.id && question.status === 'open').length;
	const previewing = previewAs ? person(previewAs) : undefined;

	return (
		<SidebarFrame
			label="Data rooms"
			menu={<OrgMenu collapsed={collapsed} />}
			collapsed={collapsed}
			onCollapsedChange={onCollapsedChange}
			drawer={drawer}
			onClose={onNavigate}
			footer={
				previewing ? (
					collapsed ? (
						<div className="flex shrink-0 justify-center border-t border-sidebar-border py-3">
							<TooltipIconButton label={`Exit preview as ${previewing.name}`} side="right" size="lg" onClick={() => setPreviewAs(null)}>
								<Eye aria-hidden="true" className="size-3.5" />
							</TooltipIconButton>
						</div>
					) : (
						<section
							aria-label="Preview"
							className="shrink-0 border-t border-sidebar-border bg-[linear-gradient(to_top,color-mix(in_oklab,var(--primary)_10%,transparent),transparent)] p-3"
						>
							<div className="flex items-center gap-2.5">
								<PersonAvatar person={previewing} size="sm" />
								<div className="min-w-0 flex-1">
									<p className="text-xs text-muted-foreground">Previewing as</p>
									<p title={previewing.name} className="truncate text-[0.8125rem] font-medium text-foreground">{previewing.name}</p>
								</div>
								<Button size="xs" variant="outline" onClick={() => setPreviewAs(null)}>
									Exit
								</Button>
							</div>
						</section>
					)
				) : null
			}
		>
			{collapsed || !showSearch ? null : (
				<SearchField
					inputRef={searchRef}
					label="Find a room"
					value={query}
					placeholder="Find a room…"
					className="h-8 shrink-0"
					onChange={(event) => setQuery(event.target.value)}
					onBlur={() => {
						if (!query) setSearchRevealed(false);
					}}
					onKeyDown={(event) => {
						if (event.key === 'Escape') {
							setQuery('');
							setSearchRevealed(false);
							event.currentTarget.blur();
						}
					}}
				/>
			)}
			<nav ref={navRef} aria-label="Main" className="flex w-full flex-col gap-3">
				<ul className="flex flex-col gap-0.5">
					<NavRow label="Home" collapsed={collapsed} active={view === 'home'} leading={<NavIcon icon={House} active={view === 'home'} />} onClick={select(() => setView('home'))} />
					{isManager ? (
						<>
							<NavRow
								label="Access map"
								collapsed={collapsed}
								active={view === 'access-map'}
								leading={<NavIcon icon={Network} active={view === 'access-map'} />}
								onClick={select(() => setView('access-map'))}
							/>
							<NavRow
								label="Activity"
								collapsed={collapsed}
								active={view === 'activity'}
								leading={<NavIcon icon={Activity} active={view === 'activity'} />}
								onClick={select(() => setView('activity'))}
							/>
						</>
					) : null}
				</ul>
				<hr className="border-sidebar-border" />
				<div className="flex flex-col gap-1">
					<div className={cn('flex h-7 items-center gap-2 ps-2', collapsed && 'justify-center ps-0')}>
						{collapsed ? null : (
							<h2 id={headingId} className="flex-1 truncate text-xs text-muted-foreground">
								Rooms
							</h2>
						)}
						{isManager ? (
							<TooltipIconButton label="New room" side={collapsed ? 'right' : 'top'} size="sm" disabled={locked} onClick={select(() => openNewRoom())}>
								<Plus aria-hidden="true" className="size-3.5" />
							</TooltipIconButton>
						) : null}
					</div>
					{groups.length === 0 ? (
						collapsed ? null : <p className="px-2 py-1 text-[0.8125rem] text-muted-foreground">{query ? 'No rooms match.' : 'No rooms yet.'}</p>
					) : (
						<div aria-labelledby={collapsed ? undefined : headingId} aria-label={collapsed ? 'Rooms' : undefined} className="flex flex-col gap-1" role="group">
							{groups.map((group) => {
								const folded = !collapsed && !query && foldedUnits.has(group.unitId);
								const name = unit(group.unitId)?.name ?? 'Rooms';
								return (
									<div key={group.unitId} className="flex flex-col gap-0.5">
										{collapsed ? null : (
											<button
												type="button"
												aria-expanded={!folded}
												onClick={() => toggleUnit(group.unitId)}
												className={cn(
													'flex h-6 cursor-pointer items-center gap-1 rounded-md pe-2 text-start text-[0.6875rem] text-subtle-foreground hover:text-foreground',
													focusRingClass,
												)}
												style={{ paddingLeft: 4 + group.depth * 8 }}
											>
												<ChevronRight aria-hidden="true" className={cn('size-3 shrink-0', !folded ? 'rotate-90' : 'rtl:-scale-x-100')} />
												<span title={name} className="truncate">{name}</span>
											</button>
										)}
										{folded ? null : (
											<ul className="flex flex-col gap-0.5">
												{group.rooms.map((room) => {
													const open = view === 'room' && roomId === room.id;
													const questions = can('manage_room', { kind: 'room', roomId: room.id }) ? openQuestions(room) : 0;
													return (
														<NavRow
															key={room.id}
															label={room.name}
															collapsed={collapsed}
															active={open}
															leading={
																collapsed ? (
																	<span aria-hidden="true" className="grid size-5 shrink-0 place-items-center text-[0.6875rem] tracking-tight">
																		{initials(room.name)}
																	</span>
																) : (
																	<span aria-hidden="true" className="w-1.5 shrink-0" />
																)
															}
															labelNode={
																<span className="flex min-w-0 items-center gap-1.5">
																	<span title={room.name} className="truncate">{room.name}</span>
																	{room.policies.restricted ? <Lock aria-hidden="true" className="size-3 shrink-0 text-subtle-foreground" /> : null}
																	<span className="sr-only">
																		{room.policies.restricted ? ', restricted' : ''}
																		{questions ? `, ${questions} open questions` : ''}
																	</span>
																</span>
															}
															trailing={questions ? <NavCount value={questions} tone="warning" /> : null}
															onClick={select(() => openRoom(room.id))}
														/>
													);
												})}
											</ul>
										)}
									</div>
								);
							})}
						</div>
					)}
				</div>
			</nav>
		</SidebarFrame>
	);
}

export { DataRoomsSidebar };
export type { DataRoomsSidebarProps };

import type { WorkspaceTheme } from '@/components/ui/workspace-kit/menu';

/* ------------------------------------------------------------------ *
 * Navigation
 * ------------------------------------------------------------------ */

export type DataRoomsView = 'home' | 'access-map' | 'activity' | 'room';

export type RoomTab = 'documents' | 'people' | 'questions' | 'insights' | 'settings';

export type DataRoomsTheme = WorkspaceTheme;

/* ------------------------------------------------------------------ *
 * People and structure
 * ------------------------------------------------------------------ */

/**
 * What someone can do. Roles bundle these; extra grants add to them; folder
 * shares grant view, edit, and delete inside a subtree.
 */
export type Permission =
	| 'view'
	| 'download'
	| 'upload'
	| 'edit'
	| 'delete'
	| 'share'
	| 'invite'
	| 'manage_members'
	| 'manage_room'
	| 'ask_assistant';

export type Person = {
	id: string;
	name: string;
	email: string;
	title?: string;
	/** Company shown beside guests, e.g. the law firm or the buyer. */
	company?: string;
	/** From outside the organization. Guests only see rooms and folders they were added to. */
	guest?: boolean;
	avatarUrl?: string;
};

/**
 * The organization and its sub-organizations. Exactly one unit has no parent:
 * the organization itself. `kind` is the label people see, e.g. "Fund".
 */
export type OrgUnit = {
	id: string;
	parentId: string | null;
	name: string;
	kind: string;
};

export type Role = {
	id: string;
	name: string;
	description?: string;
	permissions: Permission[];
	/** Picked when nobody chooses a role, e.g. for invites. */
	isDefault?: boolean;
};

export type MembershipScope = { kind: 'unit' | 'room'; id: string };

export type MembershipStatus = 'active' | 'invited' | 'suspended';

export type Membership = {
	id: string;
	personId: string;
	scope: MembershipScope;
	/** Owners hold every permission and cannot be removed by admins. */
	owner?: boolean;
	/** Admins hold every permission. */
	admin?: boolean;
	roleId?: string;
	/** Permissions granted on top of the role. */
	extraPermissions?: Permission[];
	/** Can open and download, never change anything. */
	readOnly?: boolean;
	status: MembershipStatus;
	/** Access ends at this time. */
	expiresAt?: string;
	invitedBy?: string;
	joinedAt?: string;
};

/**
 * How membership in a unit carries into its sub-units and rooms. Owners and
 * admins usually follow; plain members only when the organization says so.
 */
export type InheritancePolicy = {
	owners: boolean;
	admins: boolean;
	members: boolean;
	/** People from outside the organization may be invited to rooms. */
	allowGuests: boolean;
};

/* ------------------------------------------------------------------ *
 * Rooms and documents
 * ------------------------------------------------------------------ */

export type RoomStatus = 'active' | 'closing' | 'archived';

export type RoomPolicies = {
	/** Documents open in the viewer but cannot be downloaded. */
	viewOnly: boolean;
	/** The viewer tiles the reader's name, email, and time over every page. */
	watermark: boolean;
	/** People who don't manage the room accept the agreement before entering. */
	requireAgreement: boolean;
	/** Members of the parent units don't join automatically; owners and admins still do when inheritance says so. */
	restricted: boolean;
};

export type RoomAgreement = {
	title: string;
	body: string;
	/** Bump to ask everyone to accept again. */
	version: number;
	updatedAt?: string;
};

export type Room = {
	id: string;
	unitId: string;
	name: string;
	description?: string;
	status: RoomStatus;
	createdAt: string;
	createdBy?: string;
	/** A deadline people should see, e.g. when bids are due. */
	closesAt?: string;
	policies: RoomPolicies;
	agreement?: RoomAgreement;
};

export type DocumentKind = 'pdf' | 'sheet' | 'doc' | 'slides' | 'image' | 'archive' | 'other';

export type DocumentVersion = {
	id: string;
	number: number;
	uploadedBy: string;
	uploadedAt: string;
	size: number;
	note?: string;
};

export type DataRoomDocument = {
	id: string;
	roomId: string;
	/** Folder path, e.g. `/02 Financials/Audited`. `/` is the room root. */
	folder: string;
	name: string;
	kind: DocumentKind;
	size: number;
	pages?: number;
	versions: DocumentVersion[];
	uploadedBy: string;
	updatedAt: string;
	/** `processing` while the host indexes a fresh upload. */
	status?: 'processing' | 'ready';
	/** Per-document overrides on top of the room's policies. */
	restrictions?: { viewOnly?: boolean; watermark?: boolean };
	tags?: string[];
};

/** A folder with no documents yet. Folders with documents come from their paths. */
export type DataRoomFolder = { roomId: string; path: string };

/** Access to one folder and everything below it, for one person. */
export type FolderShare = {
	id: string;
	roomId: string;
	folder: string;
	personId: string;
	can: { view: boolean; edit: boolean; delete: boolean };
	expiresAt?: string;
	createdBy: string;
	createdAt: string;
};

export type RoomInvite = {
	id: string;
	roomId: string;
	email: string;
	roleId: string;
	invitedBy: string;
	invitedAt: string;
	expiresAt?: string;
};

export type AgreementAcceptance = {
	roomId: string;
	personId: string;
	version: number;
	acceptedAt: string;
};

/* ------------------------------------------------------------------ *
 * Activity, questions, and the assistant
 * ------------------------------------------------------------------ */

export type ActivityKind =
	| 'view'
	| 'download'
	| 'upload'
	| 'version'
	| 'move'
	| 'delete'
	| 'share'
	| 'unshare'
	| 'invite'
	| 'join'
	| 'role'
	| 'remove'
	| 'agreement'
	| 'question'
	| 'answer'
	| 'settings';

export type ActivityEvent = {
	id: string;
	at: string;
	actorId: string;
	kind: ActivityKind;
	roomId: string;
	documentId?: string;
	/** The person an access change was about. */
	subjectId?: string;
	/** Short free text, e.g. a folder path or a role name. */
	detail?: string;
	/** Seconds spent reading, for `view`. */
	seconds?: number;
};

export type QuestionStatus = 'open' | 'answered' | 'closed';

export type QuestionMessage = {
	id: string;
	authorId: string;
	at: string;
	body: string;
};

export type Citation = {
	documentId: string;
	page?: number;
	quote?: string;
};

export type QuestionThread = {
	id: string;
	roomId: string;
	documentId?: string;
	askedBy: string;
	askedAt: string;
	title: string;
	status: QuestionStatus;
	assigneeId?: string;
	messages: QuestionMessage[];
	/** A drafted answer an editor can send as is or change. */
	draft?: { body: string; citations: Citation[] };
};

export type AssistantAnswer = {
	text: string;
	citations: Citation[];
};

export type AssistantReply = AssistantAnswer & {
	/** Words that pick this reply for a prompt. */
	match: string[];
};

/** Scripted answers for the room assistant when the host does not run one. */
export type AssistantScript = {
	suggestions: string[];
	replies: AssistantReply[];
	fallback: string;
};

/* ------------------------------------------------------------------ *
 * The template's contract
 * ------------------------------------------------------------------ */

/**
 * Everything the template renders. Map it from your data room API: people,
 * the organization and its units, rooms, roles, memberships, documents,
 * folder shares, invites, agreement acceptances, activity, and questions.
 */
export type DataRoomsData = {
	/** The clock relative dates and expiries are measured from. Pass a fixed value for identical server and client output. */
	clock: string;
	org: { name: string };
	/** The person using the workspace. */
	viewerId: string;
	people: Person[];
	units: OrgUnit[];
	rooms: Room[];
	roles: Role[];
	memberships: Membership[];
	inheritance: InheritancePolicy;
	documents: DataRoomDocument[];
	folders?: DataRoomFolder[];
	shares: FolderShare[];
	invites: RoomInvite[];
	acceptances: AgreementAcceptance[];
	activity: ActivityEvent[];
	questions: QuestionThread[];
	assistant?: AssistantScript;
};

/** Changes the template asks the host to make. Reject to keep the dialog open with your message. */
export type DataRoomsCommand =
	| { type: 'create-room'; room: Room }
	| { type: 'update-room'; roomId: string; patch: Partial<Pick<Room, 'name' | 'description' | 'status' | 'closesAt' | 'policies' | 'agreement'>> }
	| { type: 'invite'; roomId: string; invites: { email: string; personId?: string }[]; roleId: string; expiresAt?: string; message?: string }
	| { type: 'revoke-invite'; inviteId: string }
	| {
			type: 'update-membership';
			membershipId: string;
			patch: Partial<Pick<Membership, 'roleId' | 'extraPermissions' | 'readOnly' | 'admin' | 'expiresAt'>>;
	  }
	| { type: 'remove-membership'; membershipId: string }
	| { type: 'create-share'; roomId: string; folder: string; personIds: string[]; can: FolderShare['can']; expiresAt?: string }
	| { type: 'revoke-share'; shareId: string }
	| { type: 'upload'; roomId: string; folder: string; files: { name: string; size: number; kind: DocumentKind; pages?: number }[] }
	| { type: 'create-folder'; roomId: string; path: string }
	| { type: 'move-documents'; documentIds: string[]; folder: string }
	| { type: 'update-document'; documentId: string; patch: { restrictions?: DataRoomDocument['restrictions'] } }
	| { type: 'update-inheritance'; inheritance: InheritancePolicy }
	| { type: 'save-role'; role: Role }
	| { type: 'accept-agreement'; roomId: string; version: number }
	| { type: 'ask-question'; roomId: string; documentId?: string; title: string; body: string }
	| { type: 'answer-question'; questionId: string; body: string; close?: boolean }
	| { type: 'set-question-status'; questionId: string; status: QuestionStatus };

/** Controls the template renders but does not own. */
export type DataRoomsAction =
	| { type: 'download'; documentId: string; versionId?: string }
	/** A document opened in the viewer, for the host's access log. */
	| { type: 'view-document'; documentId: string }
	| { type: 'export-activity'; roomId?: string }
	| { type: 'search'; query: string }
	| { type: 'contact'; personId: string }
	| { type: 'org-menu'; item: 'organization-settings' | 'profile' | 'support' | 'log-out' };

/** What the room assistant is asked; answer with text and the documents it drew on. */
export type AssistantRequest = { roomId: string; prompt: string; viewerId: string; documentId?: string };

'use client';

import * as React from 'react';

import { useDataRooms } from '@/components/ui/data-rooms/data-rooms-context';
import type { DataRoomsCommand } from '@/components/ui/data-rooms/types';

const FALLBACK = 'That change couldn’t be saved. Try again.';

/**
 * Runs commands for one control or form: tracks whether one is pending, keeps
 * the host's error message, and reports whether changes are locked because
 * the workspace is being previewed as someone else. Views show controls by
 * `can()` alone and disable them with `locked`, so a preview shows exactly
 * what the person would see.
 */
export function useCommand() {
	const { run, previewAs } = useDataRooms();
	const [pending, setPending] = React.useState(false);
	const [error, setError] = React.useState<string | null>(null);

	/** Resolves true once the host saved the change, false when it refused. */
	const execute = React.useCallback(
		async (command: DataRoomsCommand) => {
			setPending(true);
			setError(null);
			try {
				await run(command);
				return true;
			} catch (reason) {
				setError(reason instanceof Error && reason.message ? reason.message : FALLBACK);
				return false;
			} finally {
				setPending(false);
			}
		},
		[run],
	);

	return {
		run: execute,
		pending,
		error,
		clearError: React.useCallback(() => setError(null), []),
		/** Changes are off while previewing as someone else. */
		locked: previewAs !== null,
	};
}
